-- ===== Snapshot of V1__Initial_Schema.sql (fresh install only) =====
-- 1. جدول المستخدمين وحالة الموافقة الإدارية
CREATE TABLE IF NOT EXISTS users (
    id UUID PRIMARY KEY,
    email VARCHAR(255) UNIQUE NOT NULL,
    password_hash TEXT NOT NULL,
    full_name VARCHAR(100),
    status VARCHAR(20) DEFAULT 'PENDING', -- PENDING, APPROVED, BANNED
    role VARCHAR(20) DEFAULT 'USER',      -- ADMIN, USER
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- 2. جدول المجموعات والأدوار
CREATE TABLE IF NOT EXISTS groups (
    id UUID PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    owner_id UUID REFERENCES users(id),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS group_members (
    group_id UUID REFERENCES groups(id) ON DELETE CASCADE,
    user_id UUID REFERENCES users(id) ON DELETE CASCADE,
    role VARCHAR(20) DEFAULT 'MEMBER', -- OWNER, ADMIN, MEMBER
    PRIMARY KEY (group_id, user_id)
);

-- ===== Snapshot of V2__Dinstar_Master_Control.sql (fresh install only) =====
-- تخزين إعدادات الجهاز الرئيسية
CREATE TABLE IF NOT EXISTS dinstar_config (
    id SERIAL PRIMARY KEY,
    device_ip VARCHAR(50) NOT NULL,
    api_port INT DEFAULT 80,
    username VARCHAR(50),
    password_hash TEXT,
    sip_server_ip VARCHAR(50),
    last_sync TIMESTAMP
);

-- تفاصيل الـ 8 منافذ (8G GSM)
CREATE TABLE IF NOT EXISTS dinstar_ports (
    port_index INT PRIMARY KEY, -- 0 to 7
    sim_number VARCHAR(20),
    operator_name VARCHAR(50),
    is_enabled BOOLEAN DEFAULT TRUE,
    total_calls BIGINT DEFAULT 0,
    total_minutes BIGINT DEFAULT 0,
    signal_threshold INT DEFAULT 20 -- الحد الأدنى للإشارة قبل التنبيه
);

-- سجل العمليات (Audit Log) لنظام Dinstar
CREATE TABLE IF NOT EXISTS dinstar_logs (
    id SERIAL PRIMARY KEY,
    event_type VARCHAR(50), -- RESTART, CONFIG_CHANGE, SMS_SENT
    description TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- ===== Snapshot of V3__Username_Approval_Accounts.sql (fresh install only) =====
-- RED accounts do not require a phone number or SIM card.
-- Guarded: live DBs created by Hibernate may lack the legacy email column.
DO $$ BEGIN
    IF EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'users' AND column_name = 'email'
    ) THEN
        ALTER TABLE users ALTER COLUMN email DROP NOT NULL;
    END IF;
END $$;

ALTER TABLE users ADD COLUMN IF NOT EXISTS red_id VARCHAR(32);
ALTER TABLE users ADD COLUMN IF NOT EXISTS username VARCHAR(40);
ALTER TABLE users ADD COLUMN IF NOT EXISTS updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE users ADD COLUMN IF NOT EXISTS approved_at TIMESTAMP;
ALTER TABLE users ADD COLUMN IF NOT EXISTS approved_by UUID;
ALTER TABLE users ADD COLUMN IF NOT EXISTS rejection_reason VARCHAR(500);
ALTER TABLE users ADD COLUMN IF NOT EXISTS last_seen BIGINT;

UPDATE users
SET red_id = COALESCE(red_id, 'RED-LEGACY-' || UPPER(SUBSTRING(REPLACE(id::text, '-', '') FROM 1 FOR 12))),
    username = COALESCE(username, 'legacy_' || LOWER(SUBSTRING(REPLACE(id::text, '-', '') FROM 1 FOR 12))),
    full_name = COALESCE(full_name, 'RED User')
WHERE red_id IS NULL OR username IS NULL OR full_name IS NULL;

ALTER TABLE users ALTER COLUMN red_id SET NOT NULL;
ALTER TABLE users ALTER COLUMN username SET NOT NULL;
ALTER TABLE users ALTER COLUMN full_name SET NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS uq_users_red_id ON users (red_id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_users_username_lower ON users (LOWER(username));
CREATE INDEX IF NOT EXISTS idx_users_status_created ON users (status, created_at);

ALTER TABLE users DROP CONSTRAINT IF EXISTS users_status_check;
ALTER TABLE users ADD CONSTRAINT users_status_check
    CHECK (status IN ('PENDING', 'APPROVED', 'REJECTED', 'SUSPENDED', 'BANNED'));

ALTER TABLE users DROP CONSTRAINT IF EXISTS users_role_check;
ALTER TABLE users ADD CONSTRAINT users_role_check
    CHECK (role IN ('USER', 'ADMIN'));

-- ===== Snapshot of V4__Device_Identity_And_Refresh_Sessions.sql (fresh install only) =====
CREATE TABLE IF NOT EXISTS user_devices (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    device_name VARCHAR(100) NOT NULL,
    platform VARCHAR(30) NOT NULL,
    identity_key BYTEA NOT NULL,
    signed_pre_key BYTEA NOT NULL,
    kyber_pre_key BYTEA NOT NULL,
    signed_pre_key_signature BYTEA NOT NULL,
    kyber_pre_key_signature BYTEA NOT NULL,
    identity_fingerprint VARCHAR(64) NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'PENDING',
    authorization_certificate VARCHAR(4096),
    certificate_expires_at TIMESTAMP,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    approved_at TIMESTAMP,
    revoked_at TIMESTAMP,
    CONSTRAINT user_devices_status_check CHECK (status IN ('PENDING', 'APPROVED', 'REVOKED')),
    CONSTRAINT uq_user_identity_fingerprint UNIQUE (user_id, identity_fingerprint)
);

CREATE INDEX IF NOT EXISTS idx_user_devices_user_status ON user_devices(user_id, status);

CREATE TABLE IF NOT EXISTS refresh_sessions (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    device_id UUID REFERENCES user_devices(id) ON DELETE CASCADE,
    token_hash VARCHAR(64) NOT NULL UNIQUE,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    expires_at TIMESTAMP NOT NULL,
    revoked_at TIMESTAMP,
    replaced_by UUID
);

CREATE INDEX IF NOT EXISTS idx_refresh_sessions_user_active ON refresh_sessions(user_id, revoked_at);
CREATE INDEX IF NOT EXISTS idx_refresh_sessions_device_active ON refresh_sessions(device_id, revoked_at);

