-- ===== Snapshot of V8__Public_PreKey_Metadata.sql (fresh install only) =====
ALTER TABLE user_devices ADD COLUMN IF NOT EXISTS registration_id INTEGER NOT NULL DEFAULT 0;
ALTER TABLE user_devices ADD COLUMN IF NOT EXISTS protocol_device_id INTEGER NOT NULL DEFAULT 0;
ALTER TABLE user_devices ADD COLUMN IF NOT EXISTS signed_pre_key_id INTEGER NOT NULL DEFAULT 0;
ALTER TABLE user_devices ADD COLUMN IF NOT EXISTS kyber_pre_key_id INTEGER NOT NULL DEFAULT 0;

-- Give legacy rows distinct temporary protocol IDs before creating the uniqueness constraint.
WITH ranked AS (
    SELECT id, ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY created_at, id) AS device_number
    FROM user_devices
)
UPDATE user_devices d SET protocol_device_id = ranked.device_number
FROM ranked WHERE d.id = ranked.id AND d.protocol_device_id = 0;

-- Pre-V8 clients may have uploaded serialized private pre-key records. Revoke them defensively.
UPDATE user_devices
SET status = 'REVOKED', revoked_at = CURRENT_TIMESTAMP,
    authorization_certificate = NULL, certificate_expires_at = NULL
WHERE registration_id = 0;

CREATE UNIQUE INDEX IF NOT EXISTS uq_user_protocol_device ON user_devices(user_id, protocol_device_id);

-- ===== Snapshot of V9__Atomic_One_Time_PreKeys.sql (fresh install only) =====
-- Public one-time pre-keys only. Private key material is generated and retained on Android.
CREATE TABLE IF NOT EXISTS one_time_ec_prekeys (
    device_id UUID NOT NULL REFERENCES user_devices(id) ON DELETE CASCADE,
    key_id INTEGER NOT NULL CHECK (key_id >= 0),
    public_key BYTEA NOT NULL CHECK (octet_length(public_key) BETWEEN 16 AND 4096),
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    consumed_at TIMESTAMP,
    PRIMARY KEY (device_id, key_id)
);

CREATE TABLE IF NOT EXISTS one_time_kyber_prekeys (
    device_id UUID NOT NULL REFERENCES user_devices(id) ON DELETE CASCADE,
    key_id INTEGER NOT NULL CHECK (key_id >= 0),
    public_key BYTEA NOT NULL CHECK (octet_length(public_key) BETWEEN 32 AND 16384),
    signature BYTEA NOT NULL CHECK (octet_length(signature) BETWEEN 32 AND 512),
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    consumed_at TIMESTAMP,
    PRIMARY KEY (device_id, key_id)
);

CREATE INDEX IF NOT EXISTS idx_ec_prekeys_available ON one_time_ec_prekeys(device_id, created_at, key_id) WHERE consumed_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_kyber_prekeys_available ON one_time_kyber_prekeys(device_id, created_at, key_id) WHERE consumed_at IS NULL;

-- ===== Snapshot of V10__Contacts_Blocks_And_Reports.sql (fresh install only) =====
CREATE TABLE IF NOT EXISTS contact_requests (
    id UUID PRIMARY KEY,
    requester_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    recipient_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    status VARCHAR(20) NOT NULL CHECK (status IN ('PENDING','ACCEPTED','REJECTED')),
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    resolved_at TIMESTAMP,
    CONSTRAINT contact_request_not_self CHECK (requester_id <> recipient_id),
    CONSTRAINT uq_contact_request_direction UNIQUE (requester_id, recipient_id)
);
CREATE INDEX IF NOT EXISTS idx_contact_requests_recipient_status ON contact_requests(recipient_id, status, created_at);

CREATE TABLE IF NOT EXISTS red_contacts (
    owner_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    contact_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (owner_id, contact_id),
    CONSTRAINT red_contact_not_self CHECK (owner_id <> contact_id)
);

CREATE TABLE IF NOT EXISTS user_blocks (
    blocker_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    blocked_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (blocker_id, blocked_id),
    CONSTRAINT user_block_not_self CHECK (blocker_id <> blocked_id)
);

CREATE TABLE IF NOT EXISTS user_reports (
    id UUID PRIMARY KEY,
    reporter_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    reported_id UUID REFERENCES users(id) ON DELETE SET NULL,
    category VARCHAR(40) NOT NULL,
    details VARCHAR(1000),
    status VARCHAR(20) NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','REVIEWING','RESOLVED','DISMISSED')),
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    reviewed_at TIMESTAMP,
    reviewed_by UUID REFERENCES users(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS idx_user_reports_status_created ON user_reports(status, created_at DESC);

