-- ══════════════════════════════════════════════════════════════════
-- V14: Call History, User Profiles, Privacy Settings, Notifications
-- PostgreSQL — البيانات العلائقية التي تحتاج JOINs و ACID
-- ══════════════════════════════════════════════════════════════════

-- ━━━━ ملف المستخدم الشخصي ━━━━
ALTER TABLE users ADD COLUMN IF NOT EXISTS avatar_media_key VARCHAR(200);
ALTER TABLE users ADD COLUMN IF NOT EXISTS about_text VARCHAR(300);
ALTER TABLE users ADD COLUMN IF NOT EXISTS status_type VARCHAR(20) NOT NULL DEFAULT 'ONLINE';
ALTER TABLE users ADD COLUMN IF NOT EXISTS status_custom_text VARCHAR(100);
ALTER TABLE users ADD COLUMN IF NOT EXISTS status_visible_to VARCHAR(20) NOT NULL DEFAULT 'EVERYONE';
ALTER TABLE users ADD COLUMN IF NOT EXISTS theme_preference VARCHAR(30) NOT NULL DEFAULT 'SOVEREIGN_DARK';
ALTER TABLE users ADD COLUMN IF NOT EXISTS accent_color VARCHAR(20) NOT NULL DEFAULT 'CYAN';
ALTER TABLE users ADD COLUMN IF NOT EXISTS font_scale REAL NOT NULL DEFAULT 1.0;
ALTER TABLE users ADD COLUMN IF NOT EXISTS chat_bubble_style VARCHAR(20) NOT NULL DEFAULT 'ROUNDED';
ALTER TABLE users ADD COLUMN IF NOT EXISTS language VARCHAR(10) NOT NULL DEFAULT 'ar';
ALTER TABLE users ADD COLUMN IF NOT EXISTS is_rtl BOOLEAN NOT NULL DEFAULT TRUE;

ALTER TABLE users ADD CONSTRAINT users_status_type_check
    CHECK (status_type IN ('ONLINE','OFFLINE','BUSY','AWAY','DO_NOT_DISTURB','INVISIBLE'));
ALTER TABLE users ADD CONSTRAINT users_status_visible_to_check
    CHECK (status_visible_to IN ('EVERYONE','CONTACTS','CONTACTS_EXCEPT','ONLY_SHARE_WITH','NOBODY'));
ALTER TABLE users ADD CONSTRAINT users_theme_preference_check
    CHECK (theme_preference IN ('SOVEREIGN_DARK','SOVEREIGN_LIGHT','OLED_BLACK','AUTO','OCEAN_BLUE','ROYAL_PURPLE','EMERALD'));
ALTER TABLE users ADD CONSTRAINT users_accent_color_check
    CHECK (accent_color IN ('CYAN','GOLD','RED','PURPLE','GREEN','ORANGE','PINK'));

-- ━━━━ إعدادات الخصوصية التفصيلية ━━━━
CREATE TABLE IF NOT EXISTS user_privacy_settings (
    user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    last_seen VARCHAR(20) NOT NULL DEFAULT 'EVERYONE',
    online_status VARCHAR(20) NOT NULL DEFAULT 'EVERYONE',
    profile_photo VARCHAR(20) NOT NULL DEFAULT 'EVERYONE',
    about VARCHAR(20) NOT NULL DEFAULT 'EVERYONE',
    status VARCHAR(20) NOT NULL DEFAULT 'CONTACTS',
    read_receipts VARCHAR(20) NOT NULL DEFAULT 'EVERYONE',
    calls VARCHAR(20) NOT NULL DEFAULT 'CONTACTS',
    groups_add VARCHAR(20) NOT NULL DEFAULT 'EVERYONE',
    live_location VARCHAR(20) NOT NULL DEFAULT 'NOBODY',
    -- أعمدة التحقق
    CONSTRAINT privacy_level_check CHECK (
        last_seen IN ('EVERYONE','CONTACTS','CONTACTS_EXCEPT','ONLY_SHARE_WITH','NOBODY') AND
        online_status IN ('EVERYONE','CONTACTS','CONTACTS_EXCEPT','ONLY_SHARE_WITH','NOBODY') AND
        profile_photo IN ('EVERYONE','CONTACTS','CONTACTS_EXCEPT','ONLY_SHARE_WITH','NOBODY') AND
        about IN ('EVERYONE','CONTACTS','CONTACTS_EXCEPT','ONLY_SHARE_WITH','NOBODY') AND
        status IN ('EVERYONE','CONTACTS','CONTACTS_EXCEPT','ONLY_SHARE_WITH','NOBODY') AND
        read_receipts IN ('EVERYONE','CONTACTS','CONTACTS_EXCEPT','ONLY_SHARE_WITH','NOBODY') AND
        calls IN ('EVERYONE','CONTACTS','CONTACTS_EXCEPT','ONLY_SHARE_WITH','NOBODY') AND
        groups_add IN ('EVERYONE','CONTACTS','CONTACTS_EXCEPT','ONLY_SHARE_WITH','NOBODY') AND
        live_location IN ('EVERYONE','CONTACTS','CONTACTS_EXCEPT','ONLY_SHARE_WITH','NOBODY')
    )
);

-- استثناءات الخصوصية (CONTACTS_EXCEPT / ONLY_SHARE_WITH)
CREATE TABLE IF NOT EXISTS privacy_exceptions (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    setting VARCHAR(30) NOT NULL, -- last_seen, profile_photo, etc.
    exception_user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_privacy_exception UNIQUE (user_id, setting, exception_user_id)
);
CREATE INDEX idx_privacy_exceptions_user_setting ON privacy_exceptions(user_id, setting);

-- ━━━━ سجل المكالمات الموحد ━━━━
CREATE TABLE IF NOT EXISTS call_history (
    id UUID PRIMARY KEY,
    caller_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    callee_id UUID REFERENCES users(id) ON DELETE CASCADE,
    call_type VARCHAR(20) NOT NULL, -- VOIP_AUDIO, VOIP_VIDEO, CONFERENCE, LIVE_BROADCAST, AUDIO_SPACE
    call_route VARCHAR(10) NOT NULL DEFAULT 'RED',
    direction VARCHAR(10) NOT NULL, -- INCOMING, OUTGOING
    status VARCHAR(15) NOT NULL DEFAULT 'RINGING', -- RINGING, ACTIVE, ENDED, MISSED, FAILED, ON_HOLD
    duration_ms BIGINT NOT NULL DEFAULT 0,
    -- Conference/Live-specific
    max_participants INTEGER,
    viewer_count INTEGER DEFAULT 0,
    -- Recording
    is_recorded BOOLEAN NOT NULL DEFAULT FALSE,
    recording_media_key VARCHAR(200),
    -- Timestamps
    started_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    answered_at TIMESTAMP,
    ended_at TIMESTAMP,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    -- Constraints
    CONSTRAINT call_type_check CHECK (call_type IN ('VOIP_AUDIO','VOIP_VIDEO','CONFERENCE','LIVE_BROADCAST','AUDIO_SPACE')),
    CONSTRAINT call_route_check CHECK (call_route = 'RED'),
    CONSTRAINT call_direction_check CHECK (direction IN ('INCOMING','OUTGOING')),
    CONSTRAINT call_status_check CHECK (status IN ('RINGING','CONNECTING','ACTIVE','ON_HOLD','ENDED','MISSED','FAILED'))
);
CREATE INDEX idx_call_history_caller ON call_history(caller_id, started_at DESC);
CREATE INDEX idx_call_history_callee ON call_history(callee_id, started_at DESC);
CREATE INDEX idx_call_history_type ON call_history(call_type, started_at DESC);
CREATE INDEX idx_call_history_status ON call_history(status, started_at DESC);

-- مشاركو المكالمات الجماعية
CREATE TABLE IF NOT EXISTS call_participants (
    call_id UUID NOT NULL REFERENCES call_history(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    joined_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    left_at TIMESTAMP,
    role VARCHAR(20) NOT NULL DEFAULT 'PARTICIPANT', -- HOST, SPEAKER, LISTENER, PARTICIPANT
    PRIMARY KEY (call_id, user_id)
);

-- ━━━━ إشعارات المستخدم ━━━━
CREATE TABLE IF NOT EXISTS user_notifications (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    type VARCHAR(40) NOT NULL, -- NEW_MESSAGE, INCOMING_CALL, MISSED_CALL, GROUP_INVITE, STORY_VIEW, SECURITY_ALERT, etc.
    title VARCHAR(200) NOT NULL,
    body TEXT NOT NULL,
    -- المرسل
    sender_id UUID REFERENCES users(id) ON DELETE SET NULL,
    sender_name VARCHAR(100),
    -- الربط
    thread_id VARCHAR(100), -- معرف المحادثة/المكالمة/المجموعة
    group_id UUID,
    -- الحالة
    is_read BOOLEAN NOT NULL DEFAULT FALSE,
    priority VARCHAR(10) NOT NULL DEFAULT 'NORMAL', -- URGENT, HIGH, NORMAL, LOW
    -- الإجراءات
    action_label VARCHAR(50),
    action_data JSONB,
    secondary_action_label VARCHAR(50),
    -- Timestamps
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    read_at TIMESTAMP,
    -- Constraints
    CONSTRAINT notif_type_check CHECK (type IN (
        'NEW_MESSAGE','GROUP_MESSAGE','MENTION',
        'INCOMING_CALL',
        'STORY_VIEW','STORY_REPLY',
        'GROUP_INVITE','GROUP_UPDATE','ROLE_CHANGE',
        'LIVE_STARTED','SPACE_STARTED',
        'SECURITY_ALERT','DEVICE_NEW','UPDATE_AVAILABLE'
    )),
    CONSTRAINT notif_priority_check CHECK (priority IN ('URGENT','HIGH','NORMAL','LOW'))
);
CREATE INDEX idx_notifications_user_unread ON user_notifications(user_id, is_read, created_at DESC);
CREATE INDEX idx_notifications_user_type ON user_notifications(user_id, type, created_at DESC);
CREATE INDEX idx_notifications_created ON user_notifications(created_at DESC);

-- ━━━━ تفضيلات الإشعارات ━━━━
CREATE TABLE IF NOT EXISTS notification_preferences (
    user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    messages BOOLEAN NOT NULL DEFAULT TRUE,
    calls BOOLEAN NOT NULL DEFAULT TRUE,
    groups BOOLEAN NOT NULL DEFAULT TRUE,
    stories BOOLEAN NOT NULL DEFAULT TRUE,
    live BOOLEAN NOT NULL DEFAULT TRUE,
    system BOOLEAN NOT NULL DEFAULT TRUE,
    security BOOLEAN NOT NULL DEFAULT TRUE,
    quiet_hours_enabled BOOLEAN NOT NULL DEFAULT FALSE,
    quiet_hours_start TIME, -- مثال: 22:00
    quiet_hours_end TIME    -- مثال: 08:00
);

-- ━━━━ المجموعات المتقدمة (SQL للعلاقات + MongoDB للمحتوى) ━━━━
ALTER TABLE groups ADD COLUMN IF NOT EXISTS description TEXT;
ALTER TABLE groups ADD COLUMN IF NOT EXISTS avatar_media_key VARCHAR(200);
ALTER TABLE groups ADD COLUMN IF NOT EXISTS privacy VARCHAR(20) NOT NULL DEFAULT 'PRIVATE';
ALTER TABLE groups ADD COLUMN IF NOT EXISTS created_by_red_id VARCHAR(32);
ALTER TABLE groups ADD COLUMN IF NOT EXISTS max_members INTEGER NOT NULL DEFAULT 256;
ALTER TABLE groups ADD COLUMN IF NOT EXISTS is_announcement BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE groups ADD COLUMN IF NOT EXISTS updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP;

ALTER TABLE groups ADD CONSTRAINT groups_privacy_check
    CHECK (privacy IN ('PUBLIC','PRIVATE','SECRET'));

-- تحديث أدوار المجموعات
ALTER TABLE group_members ADD COLUMN IF NOT EXISTS custom_title VARCHAR(50);
ALTER TABLE group_members ADD COLUMN IF NOT EXISTS joined_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE group_members ADD COLUMN IF NOT EXISTS is_muted BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE group_members ADD COLUMN IF NOT EXISTS is_pinned BOOLEAN NOT NULL DEFAULT FALSE;

-- Drop old constraint if exists and add new one
ALTER TABLE group_members DROP CONSTRAINT IF EXISTS group_members_role_check;
ALTER TABLE group_members ADD CONSTRAINT group_members_role_check
    CHECK (role IN ('OWNER','ADMIN','MODERATOR','MEMBER'));

-- مميزات المجموعة
CREATE TABLE IF NOT EXISTS group_features (
    group_id UUID PRIMARY KEY REFERENCES groups(id) ON DELETE CASCADE,
    messages BOOLEAN NOT NULL DEFAULT TRUE,
    media BOOLEAN NOT NULL DEFAULT TRUE,
    voice_notes BOOLEAN NOT NULL DEFAULT TRUE,
    polls BOOLEAN NOT NULL DEFAULT TRUE,
    calls BOOLEAN NOT NULL DEFAULT TRUE,
    live BOOLEAN NOT NULL DEFAULT FALSE,
    links BOOLEAN NOT NULL DEFAULT TRUE,
    files BOOLEAN NOT NULL DEFAULT TRUE
);

-- دعوات المجموعات
CREATE TABLE IF NOT EXISTS group_invites (
    id UUID PRIMARY KEY,
    group_id UUID NOT NULL REFERENCES groups(id) ON DELETE CASCADE,
    inviter_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    invitee_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    status VARCHAR(20) NOT NULL DEFAULT 'PENDING', -- PENDING, ACCEPTED, REJECTED, EXPIRED
    expires_at TIMESTAMP,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    resolved_at TIMESTAMP,
    CONSTRAINT group_invite_status_check CHECK (status IN ('PENDING','ACCEPTED','REJECTED','EXPIRED'))
);
CREATE INDEX idx_group_invites_invitee ON group_invites(invitee_id, status, created_at DESC);

-- ━━━━ المشاهدون للقصص ━━━━
CREATE TABLE IF NOT EXISTS story_viewers (
    story_id VARCHAR(40) NOT NULL, -- مرتبط بـ MongoDB StoryDocument
    viewer_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    viewed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    reaction VARCHAR(10), -- ❤️ 🔥 😢 etc.
    PRIMARY KEY (story_id, viewer_id)
);
CREATE INDEX idx_story_viewers_story ON story_viewers(story_id, viewed_at DESC);

-- ━━━━ إحصائيات الاستخدام ━━━━
CREATE TABLE IF NOT EXISTS usage_stats (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    stat_date DATE NOT NULL,
    messages_sent INTEGER NOT NULL DEFAULT 0,
    messages_received INTEGER NOT NULL DEFAULT 0,
    calls_outgoing INTEGER NOT NULL DEFAULT 0,
    calls_incoming INTEGER NOT NULL DEFAULT 0,
    calls_duration_seconds INTEGER NOT NULL DEFAULT 0,
    stories_posted INTEGER NOT NULL DEFAULT 0,
    stories_viewed INTEGER NOT NULL DEFAULT 0,
    media_uploaded INTEGER NOT NULL DEFAULT 0,
    media_bytes_uploaded BIGINT NOT NULL DEFAULT 0,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(user_id, stat_date)
);
CREATE INDEX idx_usage_stats_user_date ON usage_stats(user_id, stat_date DESC);

-- ===== Snapshot of V15__Billing_CDR_RateLimit_Encryption.sql (fresh install only) =====
-- ══════════════════════════════════════════════════════════════════
-- V15: Rate Limiting, Encryption Sessions
-- PostgreSQL — البيانات المالية والتشغيلية التي تحتاج ACID
-- ══════════════════════════════════════════════════════════════════

-- ━━━━ Rate Limiting ━━━━
CREATE TABLE IF NOT EXISTS rate_limit_rules (
    id UUID PRIMARY KEY,
    endpoint_pattern VARCHAR(200) NOT NULL, -- "/api/auth/login", "/api/calls/*"
    limit_per_minute INTEGER NOT NULL,
    limit_per_hour INTEGER NOT NULL,
    limit_per_day INTEGER NOT NULL,
    scope VARCHAR(20) NOT NULL DEFAULT 'USER', -- USER, IP, GLOBAL
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT rate_limit_scope_check CHECK (scope IN ('USER','IP','GLOBAL'))
);
CREATE INDEX idx_rate_limit_endpoint ON rate_limit_rules(endpoint_pattern, is_active);

-- ━━━━ جلسات التشفير ━━━━
CREATE TABLE IF NOT EXISTS encryption_sessions (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    remote_user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    remote_device_id INTEGER NOT NULL,
    session_state BYTEA NOT NULL, -- serialized Signal protocol session
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_used_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_encryption_session UNIQUE (user_id, remote_user_id, remote_device_id)
);
CREATE INDEX idx_encryption_sessions_user ON encryption_sessions(user_id, last_used_at DESC);

-- ━━━━ المفاتيح المرسلة (Sent PreKeys) ━━━━
CREATE TABLE IF NOT EXISTS sent_prekey_records (
    id UUID PRIMARY KEY,
    device_id UUID NOT NULL REFERENCES user_devices(id) ON DELETE CASCADE,
    key_id INTEGER NOT NULL,
    key_type VARCHAR(10) NOT NULL, -- EC, KYBER
    public_key BYTEA NOT NULL,
    sent_to_user_id UUID REFERENCES users(id) ON DELETE SET NULL,
    sent_to_device_id INTEGER,
    sent_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    consumed_at TIMESTAMP,
    CONSTRAINT sent_prekey_type_check CHECK (key_type IN ('EC','KYBER'))
);
CREATE INDEX idx_sent_prekeys_device ON sent_prekey_records(device_id, key_type, consumed_at);

-- ━━━━ تتبع تسليم الرسائل ━━━━
CREATE TABLE IF NOT EXISTS message_delivery_receipts (
    id UUID PRIMARY KEY,
    message_uuid VARCHAR(40) NOT NULL, -- مرتبط بـ MongoDB MessageDocument
    recipient_user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    recipient_device_id INTEGER NOT NULL,
    delivery_status VARCHAR(20) NOT NULL DEFAULT 'PENDING', -- PENDING, DELIVERED, READ, FAILED
    delivered_at TIMESTAMP,
    read_at TIMESTAMP,
    failed_reason VARCHAR(200),
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT delivery_status_check CHECK (delivery_status IN ('PENDING','DELIVERED','READ','FAILED')),
    CONSTRAINT uq_message_delivery UNIQUE (message_uuid, recipient_user_id, recipient_device_id)
);
CREATE INDEX idx_delivery_receipts_recipient ON message_delivery_receipts(recipient_user_id, delivery_status, created_at DESC);
CREATE INDEX idx_delivery_receipts_message ON message_delivery_receipts(message_uuid);

-- ━━━━ جداول مفاتيح البحث ━━━━
-- Full-text search index for users
CREATE INDEX IF NOT EXISTS idx_users_name_search ON users USING gin(to_tsvector('arabic', COALESCE(full_name,'') || ' ' || COALESCE(username,'')));
CREATE INDEX IF NOT EXISTS idx_users_red_id_prefix ON users(red_id varchar_pattern_ops);
CREATE INDEX IF NOT EXISTS idx_users_username_prefix ON users(LOWER(username) varchar_pattern_ops);

-- ━━━━ قواعد Rate Limit الافتراضية ━━━━
INSERT INTO rate_limit_rules(id, endpoint_pattern, limit_per_minute, limit_per_hour, limit_per_day, scope)
VALUES
    ('10000000-0000-0000-0000-000000000001', '/api/auth/login', 5, 20, 100, 'IP'),
    ('10000000-0000-0000-0000-000000000002', '/api/auth/register', 3, 10, 30, 'IP'),
    ('10000000-0000-0000-0000-000000000003', '/api/messages/*', 60, 1000, 10000, 'USER'),
    ('10000000-0000-0000-0000-000000000004', '/api/calls/*', 10, 60, 200, 'USER'),
    ('10000000-0000-0000-0000-000000000006', '/api/stories/*', 20, 200, 500, 'USER')
ON CONFLICT (id) DO NOTHING;

-- ===== Snapshot of V16__Sim_Inventory_Notes.sql (fresh install only) =====
-- جرد شرائح SIM: ملاحظات إدارية اختيارية على كل منفذ بوابة.
ALTER TABLE gateway_port_snapshots ADD COLUMN IF NOT EXISTS note VARCHAR(200);

-- ===== Snapshot of V17__User_Security_Operations.sql (fresh install only) =====
-- عمليات الأمان: إعادة تعيين كلمة مرور مؤقتة + المسح عن بُعد للأجهزة المُدارة.
ALTER TABLE users ADD COLUMN IF NOT EXISTS password_reset_required BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE users ADD COLUMN IF NOT EXISTS password_reset_issued_at TIMESTAMP;
ALTER TABLE users ADD COLUMN IF NOT EXISTS remote_wipe_status VARCHAR(20) NOT NULL DEFAULT 'NONE'
    CHECK (remote_wipe_status IN ('NONE','REQUESTED','ACKNOWLEDGED','COMPLETED','FAILED'));
ALTER TABLE users ADD COLUMN IF NOT EXISTS remote_wipe_requested_at TIMESTAMP;
ALTER TABLE users ADD COLUMN IF NOT EXISTS remote_wipe_completed_at TIMESTAMP;
ALTER TABLE users ADD COLUMN IF NOT EXISTS managed_device_wipe_allowed BOOLEAN NOT NULL DEFAULT FALSE;

-- ===== Snapshot of V18__Gateway_SIM_Inventory.sql (fresh install only) =====
-- جرد شرائح SIM التشغيلي: تسميات وتحقق يدوي فقط (لا MSISDN/IMSI كامل).
CREATE TABLE IF NOT EXISTS gateway_sim_inventory (
    gateway_id UUID NOT NULL REFERENCES telecom_gateways(id) ON DELETE CASCADE,
    port_index INTEGER NOT NULL CHECK (port_index BETWEEN 0 AND 31),
    operator_label VARCHAR(50),
    sim_label VARCHAR(80),
    verification_state VARCHAR(20) NOT NULL DEFAULT 'UNKNOWN'
        CHECK (verification_state IN ('UNKNOWN','PENDING','VERIFIED','MISMATCH','NOT_PRESENT')),
    verification_method VARCHAR(20)
        CHECK (verification_method IS NULL OR verification_method IN ('MANUAL','USSD','SMS','CALL')),
    msisdn_masked VARCHAR(16),
    verified_at TIMESTAMP,
    verified_by UUID REFERENCES users(id) ON DELETE SET NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (gateway_id, port_index),
    CHECK (msisdn_masked IS NULL OR msisdn_masked ~ '^••••[0-9]{4}$')
);

CREATE INDEX IF NOT EXISTS idx_gateway_sim_inventory_state ON gateway_sim_inventory(gateway_id, verification_state);

-- ===== Snapshot of V19__Admin_Audit_Analytics_Optimization.sql (fresh install only) =====
-- ══════════════════════════════════════════════════════════════════
-- V19: Admin Audit Trail, Analytics & Performance Optimization
-- PostgreSQL — تحسينات لإدارة النظام والـ Analytics
-- ══════════════════════════════════════════════════════════════════

-- ━━━━ Audit Log محسّن (Admin Actions) ━━━━
CREATE TABLE IF NOT EXISTS admin_audit_log (
    id UUID PRIMARY KEY,
    admin_id UUID NOT NULL REFERENCES users(id) ON DELETE SET NULL,
    admin_username VARCHAR(100),  -- denormalized for fast lookup
    action VARCHAR(50) NOT NULL,  -- USER_APPROVED, USER_BANNED, CONFIG_CHANGED, MEDIA_DELETED, etc.
    category VARCHAR(30) NOT NULL, -- USER, SYSTEM, MEDIA, BILLING, SECURITY
    target_type VARCHAR(30),       -- USER, GROUP, MEDIA, CONFIG, etc.
    target_id VARCHAR(100),        -- reference to the affected entity
    description TEXT,
    metadata JSONB,                 -- before/after values, context
    ip_address INET,
    user_agent TEXT,
    severity VARCHAR(10) NOT NULL DEFAULT 'INFO', -- INFO, WARNING, CRITICAL
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT admin_audit_action_check CHECK (action IN (
        'USER_APPROVED','USER_BANNED','USER_REJECTED','USER_UNBANNED','USER_PROMOTED','USER_DEMOTED',
        'MEDIA_DELETED','MEDIA_GRANTED','MEDIA_REVOKED',
        'GROUP_CREATED','GROUP_DELETED','GROUP_MEMBER_ADDED','GROUP_MEMBER_REMOVED',
        'CONFIG_CHANGED',
        'BILLING_RATE_CHANGED','BILLING_CDR_EXPORTED',
        'SECURITY_ALERT','LOGIN_FAILED','PERMISSION_GRANTED','PERMISSION_REVOKED',
        'BACKUP_CREATED','BACKUP_RESTORED',
        'STORY_DELETED','POST_DELETED','CALL_TERMINATED'
    )),
    CONSTRAINT admin_audit_category_check CHECK (category IN (
        'USER','SYSTEM','MEDIA','BILLING','SECURITY','CONTENT','CALL'
    )),
    CONSTRAINT admin_audit_severity_check CHECK (severity IN ('INFO','WARNING','CRITICAL'))
);
CREATE INDEX IF NOT EXISTS idx_admin_audit_admin ON admin_audit_log(admin_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_admin_audit_action ON admin_audit_log(action, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_admin_audit_category ON admin_audit_log(category, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_admin_audit_severity ON admin_audit_log(severity, created_at DESC) WHERE severity = 'CRITICAL';
CREATE INDEX IF NOT EXISTS idx_admin_audit_created ON admin_audit_log(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_admin_audit_target ON admin_audit_log(target_type, target_id);

-- ━━━━ System Analytics (Dashboard Stats) ━━━━
CREATE TABLE IF NOT EXISTS system_analytics (
    id UUID PRIMARY KEY,
    stat_date DATE NOT NULL,
    -- المستخدمين
    total_users INTEGER NOT NULL DEFAULT 0,
    new_users INTEGER NOT NULL DEFAULT 0,
    active_users_dau INTEGER NOT NULL DEFAULT 0,  -- Daily Active Users
    active_users_mau INTEGER NOT NULL DEFAULT 0,  -- Monthly Active Users
    pending_approvals INTEGER NOT NULL DEFAULT 0,
    banned_users INTEGER NOT NULL DEFAULT 0,
    -- الرسائل
    messages_sent INTEGER NOT NULL DEFAULT 0,
    messages_delivered INTEGER NOT NULL DEFAULT 0,
    messages_read INTEGER NOT NULL DEFAULT 0,
    voice_messages INTEGER NOT NULL DEFAULT 0,
    media_uploads INTEGER NOT NULL DEFAULT 0,
    media_bytes_uploaded BIGINT NOT NULL DEFAULT 0,
    -- المكالمات
    calls_total INTEGER NOT NULL DEFAULT 0,
    calls_audio INTEGER NOT NULL DEFAULT 0,
    calls_video INTEGER NOT NULL DEFAULT 0,
    calls_conference INTEGER NOT NULL DEFAULT 0,
    calls_live INTEGER NOT NULL DEFAULT 0,
    calls_duration_seconds BIGINT NOT NULL DEFAULT 0,
    -- المكالمات الفاشلة
    calls_failed INTEGER NOT NULL DEFAULT 0,
    calls_missed INTEGER NOT NULL DEFAULT 0,
    -- المجموعات
    groups_created INTEGER NOT NULL DEFAULT 0,
    groups_active INTEGER NOT NULL DEFAULT 0,
    -- القصص والمنشورات
    stories_posted INTEGER NOT NULL DEFAULT 0,
    stories_viewed INTEGER NOT NULL DEFAULT 0,
    posts_created INTEGER NOT NULL DEFAULT 0,
    posts_reactions INTEGER NOT NULL DEFAULT 0,
    -- التخزين
    storage_used_bytes BIGINT NOT NULL DEFAULT 0,
    media_objects_count INTEGER NOT NULL DEFAULT 0,
    -- أمان
    security_alerts INTEGER NOT NULL DEFAULT 0,
    blocked_attempts INTEGER NOT NULL DEFAULT 0,
    -- Timestamps
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(stat_date)
);
CREATE INDEX IF NOT EXISTS idx_system_analytics_date ON system_analytics(stat_date DESC);

-- ━━━━ System Health (Real-time metrics) ━━━━
CREATE TABLE IF NOT EXISTS system_health (
    id UUID PRIMARY KEY,
    component VARCHAR(50) NOT NULL, -- DATABASE, REDIS, MINIO, SIGNAL, RABBITMQ, etc.
    status VARCHAR(20) NOT NULL DEFAULT 'HEALTHY', -- HEALTHY, DEGRADED, DOWN
    -- Metrics
    cpu_usage REAL,            -- 0-100
    memory_usage REAL,         -- 0-100
    disk_usage REAL,           -- 0-100
    active_connections INTEGER,
    requests_per_second REAL,
    average_response_ms REAL,
    error_rate REAL,            -- 0-100 (%)
    -- Details
    details JSONB,              -- component-specific metrics
    -- Timestamps
    last_check_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT system_health_status_check CHECK (status IN ('HEALTHY','DEGRADED','DOWN'))
);
CREATE INDEX IF NOT EXISTS idx_system_health_component ON system_health(component, last_check_at DESC);
CREATE INDEX IF NOT EXISTS idx_system_health_status ON system_health(status, last_check_at DESC) WHERE status != 'HEALTHY';

-- ━━━━ Admin Sessions (Active admin tracking) ━━━━
CREATE TABLE IF NOT EXISTS admin_sessions (
    id UUID PRIMARY KEY,
    admin_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    session_token_hash VARCHAR(128) NOT NULL, -- hashed for security
    ip_address INET,
    user_agent TEXT,
    location VARCHAR(100),     -- city/country if available
    device_info JSONB,         -- browser, OS, screen
    started_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_active_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    expires_at TIMESTAMP NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    terminated_at TIMESTAMP,
    termination_reason VARCHAR(50) -- LOGOUT, EXPIRED, FORCE_TERMINATED, SECURITY
);
CREATE INDEX IF NOT EXISTS idx_admin_sessions_admin ON admin_sessions(admin_id, is_active, last_active_at DESC);
CREATE INDEX IF NOT EXISTS idx_admin_sessions_token ON admin_sessions(session_token_hash);
CREATE INDEX IF NOT EXISTS idx_admin_sessions_expires ON admin_sessions(expires_at) WHERE is_active = TRUE;

-- ━━━━ Feature Flags (Enable/disable features per user) ━━━━
CREATE TABLE IF NOT EXISTS feature_flags (
    id UUID PRIMARY KEY,
    flag_name VARCHAR(50) UNIQUE NOT NULL,
    description TEXT,
    enabled BOOLEAN NOT NULL DEFAULT FALSE,
    -- Rollout
    rollout_percentage INTEGER NOT NULL DEFAULT 0 CHECK (rollout_percentage BETWEEN 0 AND 100),
    target_user_ids UUID[] DEFAULT '{}',
    target_groups TEXT[] DEFAULT '{}', -- e.g. {'BETA_TESTERS', 'ADMINS'}
    -- Configuration
    config JSONB,                -- flag-specific configuration
    -- Metadata
    created_by UUID REFERENCES users(id),
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by UUID REFERENCES users(id),
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    expires_at TIMESTAMP         -- optional expiration
);
CREATE INDEX IF NOT EXISTS idx_feature_flags_name ON feature_flags(flag_name);
CREATE INDEX IF NOT EXISTS idx_feature_flags_enabled ON feature_flags(enabled, expires_at);

-- ━━━━ User Reports (content moderation) — ترقية تراكمية لجدول V10 الموجود مسبقاً ━━━━
-- V10 أنشأ user_reports بمخطط أقدم (reported_id/details)؛ لذلك CREATE TABLE IF NOT EXISTS
-- هنا كان يتخطى الإنشاء بصمت ثم تفشل الفهارس على الأعمدة الجديدة (خطأ الإقلاع target_user_id).
-- الحل: تطوير الجدول القائم بإضافة أعمدة كيان UserReport فقط (validate يتسامح مع الأعمدة الزائدة).
ALTER TABLE user_reports ADD COLUMN IF NOT EXISTS target_user_id UUID REFERENCES users(id) ON DELETE CASCADE;
ALTER TABLE user_reports ADD COLUMN IF NOT EXISTS target_content_type VARCHAR(30); -- MESSAGE, POST, STORY, PROFILE, GROUP
ALTER TABLE user_reports ADD COLUMN IF NOT EXISTS target_content_id VARCHAR(100);  -- ID of the reported content
ALTER TABLE user_reports ADD COLUMN IF NOT EXISTS reason TEXT;
ALTER TABLE user_reports ADD COLUMN IF NOT EXISTS evidence JSONB;                  -- screenshots, message IDs, etc.
ALTER TABLE user_reports ADD COLUMN IF NOT EXISTS assigned_admin_id UUID REFERENCES users(id);
ALTER TABLE user_reports ADD COLUMN IF NOT EXISTS resolution VARCHAR(30);          -- WARNING_ISSUED, USER_BANNED, CONTENT_REMOVED, NO_ACTION
ALTER TABLE user_reports ADD COLUMN IF NOT EXISTS admin_notes TEXT;
ALTER TABLE user_reports ADD COLUMN IF NOT EXISTS resolved_at TIMESTAMP;
-- قيد V10 القديم على status يسمح بـ OPEN كحالة افتتاحية، بينما الكيان يبدأ بـ PENDING → نوحّد القائمتين
ALTER TABLE user_reports DROP CONSTRAINT IF EXISTS user_reports_status_check;
ALTER TABLE user_reports ADD CONSTRAINT user_reports_status_check
    CHECK (status IN ('OPEN','PENDING','REVIEWING','RESOLVED','DISMISSED'));
CREATE INDEX IF NOT EXISTS idx_user_reports_status ON user_reports(status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_user_reports_reporter ON user_reports(reporter_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_user_reports_target_user ON user_reports(target_user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_user_reports_assigned ON user_reports(assigned_admin_id, status) WHERE status IN ('PENDING','REVIEWING');

-- ━━━━ System Announcements ━━━━
CREATE TABLE IF NOT EXISTS system_announcements (
    id UUID PRIMARY KEY,
    title VARCHAR(200) NOT NULL,
    body TEXT NOT NULL,
    type VARCHAR(20) NOT NULL DEFAULT 'INFO', -- INFO, WARNING, MAINTENANCE, FEATURE
    target_audience VARCHAR(20) NOT NULL DEFAULT 'ALL', -- ALL, ADMINS, USERS, SPECIFIC
    target_user_ids UUID[] DEFAULT '{}',
    -- Display
    priority INTEGER NOT NULL DEFAULT 0,  -- 0=normal, 1=high, 2=critical
    is_dismissible BOOLEAN NOT NULL DEFAULT TRUE,
    show_from TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    show_until TIMESTAMP,
    -- Status
    is_published BOOLEAN NOT NULL DEFAULT FALSE,
    published_by UUID REFERENCES users(id),
    published_at TIMESTAMP,
    -- Timestamps
    created_by UUID NOT NULL REFERENCES users(id),
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT announcements_type_check CHECK (type IN ('INFO','WARNING','MAINTENANCE','FEATURE','PROMO')),
    CONSTRAINT announcements_audience_check CHECK (target_audience IN ('ALL','ADMINS','USERS','SPECIFIC'))
);
CREATE INDEX IF NOT EXISTS idx_announcements_published ON system_announcements(is_published, priority DESC, show_from);
CREATE INDEX IF NOT EXISTS idx_announcements_active ON system_announcements(is_published, show_until) WHERE is_published = TRUE;

-- ━━━━ Backup History ━━━━
CREATE TABLE IF NOT EXISTS backup_history (
    id UUID PRIMARY KEY,
    backup_type VARCHAR(20) NOT NULL, -- FULL, INCREMENTAL, CONFIG_ONLY, USER_DATA
    -- Storage
    storage_location VARCHAR(500) NOT NULL, -- path/URL to backup file
    size_bytes BIGINT NOT NULL,
    -- Status
    status VARCHAR(20) NOT NULL DEFAULT 'IN_PROGRESS', -- IN_PROGRESS, COMPLETED, FAILED, VERIFIED
    started_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    completed_at TIMESTAMP,
    -- Verification
    checksum VARCHAR(128),         -- SHA-256 of the backup file
    verified_at TIMESTAMP,
    verified_by UUID REFERENCES users(id),
    -- Restore info
    last_restored_at TIMESTAMP,
    restore_count INTEGER NOT NULL DEFAULT 0,
    -- Metadata
    triggered_by VARCHAR(20) NOT NULL DEFAULT 'SCHEDULED', -- SCHEDULED, MANUAL, API
    initiated_by UUID REFERENCES users(id),
    notes TEXT,
    CONSTRAINT backup_type_check CHECK (backup_type IN ('FULL','INCREMENTAL','CONFIG_ONLY','USER_DATA','MEDIA')),
    CONSTRAINT backup_status_check CHECK (status IN ('IN_PROGRESS','COMPLETED','FAILED','VERIFIED'))
);
CREATE INDEX IF NOT EXISTS idx_backup_history_type ON backup_history(backup_type, started_at DESC);
CREATE INDEX IF NOT EXISTS idx_backup_history_status ON backup_history(status, started_at DESC);
CREATE INDEX IF NOT EXISTS idx_backup_history_completed ON backup_history(completed_at DESC) WHERE status IN ('COMPLETED','VERIFIED');

-- ━━━━ Views for Dashboard Quick Stats ━━━━
CREATE OR REPLACE VIEW v_user_stats AS
SELECT
    COUNT(*) FILTER (WHERE TRUE) AS total_users,
    COUNT(*) FILTER (WHERE status = 'PENDING') AS pending_users,
    COUNT(*) FILTER (WHERE status = 'APPROVED') AS approved_users,
    COUNT(*) FILTER (WHERE status = 'BANNED') AS banned_users,
    COUNT(*) FILTER (WHERE created_at > NOW() - INTERVAL '24 hours') AS new_users_24h,
    COUNT(*) FILTER (WHERE created_at > NOW() - INTERVAL '7 days') AS new_users_7d,
    COUNT(*) FILTER (WHERE created_at > NOW() - INTERVAL '30 days') AS new_users_30d
FROM users;

-- الرسائل تعيش في MongoDB (MessageDocument) ولا يوجد لها جدول PostgreSQL إطلاقاً —
-- إنشاء العرض بـ FROM messages كان سيفشل حتماً (relation does not exist).
-- عرض توافقي بقيم صفرية حتى تُغذّى إحصاءات الرسائل من طبقة التطبيق (لا مستدعي له حالياً).
CREATE OR REPLACE VIEW v_message_stats AS
SELECT
    0::BIGINT AS total_messages,
    0::BIGINT AS text_messages,
    0::BIGINT AS voice_messages,
    0::BIGINT AS image_messages,
    0::BIGINT AS video_messages,
    0::BIGINT AS file_messages,
    0::BIGINT AS messages_24h,
    0::BIGINT AS messages_7d,
    0::BIGINT AS sent_count,
    0::BIGINT AS delivered_count,
    0::BIGINT AS read_count;

CREATE OR REPLACE VIEW v_call_stats AS
SELECT
    COUNT(*) AS total_calls,
    COUNT(*) FILTER (WHERE call_type = 'VOIP_AUDIO') AS audio_calls,
    COUNT(*) FILTER (WHERE call_type = 'VOIP_VIDEO') AS video_calls,
    COUNT(*) FILTER (WHERE call_type = 'CONFERENCE') AS conference_calls,
    COUNT(*) FILTER (WHERE call_type = 'LIVE_BROADCAST') AS live_calls,
    COUNT(*) FILTER (WHERE call_route = 'RED') AS red_calls,
    COUNT(*) FILTER (WHERE status = 'MISSED') AS missed_calls,
    COUNT(*) FILTER (WHERE status = 'FAILED') AS failed_calls,
    SUM(duration_ms) AS total_duration_ms,
    AVG(duration_ms) AS avg_duration_ms
FROM call_history;

-- ━━━━ Function for Auto-cleanup of Expired Records ━━━━
CREATE OR REPLACE FUNCTION cleanup_expired_admin_sessions()
RETURNS INTEGER AS $$
DECLARE
    deleted_count INTEGER;
BEGIN
    UPDATE admin_sessions
    SET is_active = FALSE, terminated_at = NOW(), termination_reason = 'EXPIRED'
    WHERE is_active = TRUE AND expires_at < NOW();
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN deleted_count;
END;
$$ LANGUAGE plpgsql;

-- ━━━━ Function for Daily Analytics Rollup ━━━━
CREATE OR REPLACE FUNCTION rollup_daily_analytics(target_date DATE DEFAULT CURRENT_DATE)
RETURNS VOID AS $$
BEGIN
    INSERT INTO system_analytics (
        id, stat_date,
        total_users, new_users, messages_sent, voice_messages,
        calls_total, calls_audio, calls_video,
        groups_active, storage_used_bytes
    )
    SELECT
        gen_random_uuid(), target_date,
        (SELECT COUNT(*) FROM users),
        (SELECT COUNT(*) FROM users WHERE DATE(created_at) = target_date),
        0, -- messages: تُحسب من MongoDB (لا جدول في PG)
        0, -- voice_messages: تُحسب من MongoDB
        (SELECT COUNT(*) FROM call_history WHERE DATE(started_at) = target_date),
        (SELECT COUNT(*) FROM call_history WHERE call_type = 'VOIP_AUDIO' AND DATE(started_at) = target_date),
        (SELECT COUNT(*) FROM call_history WHERE call_type = 'VOIP_VIDEO' AND DATE(started_at) = target_date),
        (SELECT COUNT(*) FROM groups),
        0 -- storage_used_bytes: تُحسب من MinIO/MongoDB (لا جدول media_objects في PG)
    ON CONFLICT (stat_date) DO UPDATE SET
        total_users = EXCLUDED.total_users,
        new_users = EXCLUDED.new_users,
        messages_sent = EXCLUDED.messages_sent,
        voice_messages = EXCLUDED.voice_messages,
        calls_total = EXCLUDED.calls_total,
        calls_audio = EXCLUDED.calls_audio,
        calls_video = EXCLUDED.calls_video,
        groups_active = EXCLUDED.groups_active,
        storage_used_bytes = EXCLUDED.storage_used_bytes,
        updated_at = NOW();
END;
$$ LANGUAGE plpgsql;

-- ━━━━ Function to Get Admin Dashboard Summary ━━━━
CREATE OR REPLACE FUNCTION get_admin_dashboard_summary()
RETURNS TABLE (
    metric_name VARCHAR(50),
    metric_value BIGINT,
    metric_change_24h BIGINT,
    metric_change_pct NUMERIC
) AS $$
BEGIN
    RETURN QUERY
    SELECT 'total_users'::VARCHAR(50), COUNT(*)::BIGINT,
        COUNT(*) FILTER (WHERE created_at > NOW() - INTERVAL '24 hours')::BIGINT,
        CASE WHEN COUNT(*) > 0
            THEN ROUND(COUNT(*) FILTER (WHERE created_at > NOW() - INTERVAL '24 hours') * 100.0 / COUNT(*), 2)
            ELSE 0 END
    FROM users
    UNION ALL
    SELECT 'pending_approvals'::VARCHAR(50), COUNT(*) FILTER (WHERE status = 'PENDING')::BIGINT,
        COUNT(*) FILTER (WHERE status = 'PENDING' AND created_at > NOW() - INTERVAL '24 hours')::BIGINT,
        0
    FROM users
    UNION ALL
    SELECT 'messages_24h'::VARCHAR(50), 0::BIGINT, 0::BIGINT, 100.0 -- تُحسب من MongoDB لاحقاً
    UNION ALL
    SELECT 'calls_24h'::VARCHAR(50), COUNT(*)::BIGINT, COUNT(*)::BIGINT, 100.0
    FROM call_history WHERE started_at > NOW() - INTERVAL '24 hours'
    UNION ALL
    SELECT 'pending_reports'::VARCHAR(50), COUNT(*)::BIGINT,
        COUNT(*) FILTER (WHERE created_at > NOW() - INTERVAL '24 hours')::BIGINT, 0
    FROM user_reports WHERE status = 'PENDING';
END;
$$ LANGUAGE plpgsql;

