ALTER TABLE users ADD COLUMN IF NOT EXISTS avatar_color VARCHAR(20);

-- ===== Snapshot of V22__Schema_Validation_Alignment.sql (fresh install only) =====
-- ══════════════════════════════════════════════════════════════════
-- V22: محاذاة المخطط مع كيانات JPA — أول اجتياز لفحص Hibernate validate في التاريخ
-- اكتُشفت بمطابقة ساكنة شاملة لكل الكيانات الـ23 مع DDL الترحيلات.
-- إضافي بالكامل: لا يلمس أي ملف مُطبَّق، ولا يحتاج مسحاً للأحجام.
-- ══════════════════════════════════════════════════════════════════

-- ━━━━ 1) مفاتيح بديلة لكيانات @Id ذات التوليد IDENTITY ━━━━
-- الجداول أُنشئت بمفاتيح مركبة فقط، بينما الكيانان EventAttendee/HashtagFollow
-- يتطلبان عمود id من نوع Long بتوليد هوية. المفاتيح المركبة تبقى كما هي.
ALTER TABLE event_attendees ADD COLUMN IF NOT EXISTS id BIGINT GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE hashtag_follows  ADD COLUMN IF NOT EXISTS id BIGINT GENERATED BY DEFAULT AS IDENTITY;

-- ━━━━ 2) محاذاة الكسور العائمة: الكيانات Double ↔ double precision ━━━━
-- v_trending_hashtags تعتمد على trending_score وPostgreSQL يمنع تغيير نوع عمود
-- تعتمد عليه عروض → نسقط العرض مؤقتاً ونعيد إنشاءه بعد التحويل.
DROP VIEW IF EXISTS v_trending_hashtags;
ALTER TABLE events    ALTER COLUMN location_lat   TYPE DOUBLE PRECISION USING location_lat::double precision;
ALTER TABLE events    ALTER COLUMN location_lng   TYPE DOUBLE PRECISION USING location_lng::double precision;
ALTER TABLE hashtags  ALTER COLUMN trending_score TYPE DOUBLE PRECISION USING trending_score::double precision;
CREATE OR REPLACE VIEW v_trending_hashtags AS
SELECT
    id, tag_name, usage_count, posts_count, trending_score,
    is_trending, last_used_at
FROM hashtags
WHERE is_blocked = FALSE
ORDER BY trending_score DESC, usage_count DESC
LIMIT 100;

-- ━━━━ 3) حقول JSONB/INET/ARRAY مقابل String في الكيانات → TEXT ━━━━
-- الكيانات تربط هذه الحقول كنصوص عادية (String?)؛ validate في Hibernate 6 يطابق
-- النوع (jsonb/inet/array تُسجَّل Types#OTHER فيرفضها) — والتطبيق لا يستخدم
-- أي معاملات JSONB/ARRAY عليها، فالتحويل إلى TEXT شفاف تماماً.
ALTER TABLE admin_audit_log       ALTER COLUMN metadata        TYPE TEXT USING metadata::text;
ALTER TABLE admin_sessions        ALTER COLUMN device_info     TYPE TEXT USING device_info::text;

-- ip_address: `host()` يقبل inet فقط. على قاعدة سبق أن حُوِّل فيها العمود إلى
-- varchar (أو أُنشئ نصيًا من الأصل) كان هذا السطر يرفع
-- `function host(character varying) does not exist` فيُسقط الترحيل بالكامل —
-- وهو ما جمّد السلسلة عند V22. الآن يُقرأ النوع الفعلي أولاً: التحويل يجري
-- بـ host() على inet وحده، ويُتجاهل إن كان العمود نصيًا بالفعل.
DO $$
DECLARE
    t record;
BEGIN
    FOR t IN
        SELECT table_name
        FROM information_schema.columns
        WHERE table_schema = 'public'
          AND table_name IN ('admin_audit_log', 'admin_sessions')
          AND column_name = 'ip_address'
          AND udt_name = 'inet'
    LOOP
        EXECUTE format(
            'ALTER TABLE %I ALTER COLUMN ip_address TYPE TEXT USING host(ip_address)',
            t.table_name
        );
    END LOOP;
END $$;
ALTER TABLE feature_flags         ALTER COLUMN config          TYPE TEXT USING config::text;
ALTER TABLE feature_flags         ALTER COLUMN target_user_ids TYPE TEXT USING target_user_ids::text;
ALTER TABLE feature_flags         ALTER COLUMN target_groups   TYPE TEXT USING target_groups::text;
ALTER TABLE system_announcements  ALTER COLUMN target_user_ids TYPE TEXT USING target_user_ids::text;
ALTER TABLE system_health         ALTER COLUMN details         TYPE TEXT USING details::text;
ALTER TABLE user_reports          ALTER COLUMN evidence        TYPE TEXT USING evidence::text;

-- ===== Snapshot of V23__Multi_Gateway_Fleet.sql (fresh install only) =====
-- ═══════════════════════════════════════════════════════════════════
-- أسطول بوابات DINSTAR — دعم عدة أجهزة UC2000-VE-8G / UC2000-VE-8T
-- ═══════════════════════════════════════════════════════════════════
-- جدول telecom_gateways كان موجودًا منذ V12 ويقبل عدة صفوف، لكن الشيفرة
-- كانت تتعامل مع بوابة واحدة فقط عبر red.dinstar.ip. هذه الهجرة تضيف
-- الحقول التي يحتاجها تشغيل أسطول حقيقي.

-- عدد المنافذ يختلف بين الطرازات (4 أو 8)، وكان مُثبّتًا في الشيفرة على 8.
ALTER TABLE telecom_gateways ADD COLUMN IF NOT EXISTS port_count INTEGER NOT NULL DEFAULT 8
    CHECK (port_count BETWEEN 1 AND 32);

-- أولوية التوجيه: الأقل رقمًا يُجرَّب أولًا عند تساوي بقية العوامل.
ALTER TABLE telecom_gateways ADD COLUMN IF NOT EXISTS routing_priority INTEGER NOT NULL DEFAULT 100;

-- نتيجة آخر فحص صحّة، لتفادي إرسال مكالمة إلى بوابة ساقطة.
ALTER TABLE telecom_gateways ADD COLUMN IF NOT EXISTS health_state VARCHAR(20) NOT NULL DEFAULT 'UNKNOWN'
    CHECK (health_state IN ('UNKNOWN','ONLINE','DEGRADED','OFFLINE'));
ALTER TABLE telecom_gateways ADD COLUMN IF NOT EXISTS last_error TEXT;
ALTER TABLE telecom_gateways ADD COLUMN IF NOT EXISTS consecutive_failures INTEGER NOT NULL DEFAULT 0;

-- اسم نظير PJSIP في Asterisk المقابل لهذه البوابة. بدونه لا يعرف الخادم
-- عبر أي trunk يُخرج المكالمة عند وجود أكثر من جهاز.
ALTER TABLE telecom_gateways ADD COLUMN IF NOT EXISTS pjsip_endpoint VARCHAR(120);

-- موقع الجهاز الفعلي — يفيد عند توزيع الأجهزة على فروع.
ALTER TABLE telecom_gateways ADD COLUMN IF NOT EXISTS site_label VARCHAR(120);

-- التعرّف التلقائي: كيف اكتُشف هذا الجهاز ومتى.
ALTER TABLE telecom_gateways ADD COLUMN IF NOT EXISTS discovery_method VARCHAR(30) NOT NULL DEFAULT 'MANUAL'
    CHECK (discovery_method IN ('MANUAL','SUBNET_SCAN','CONFIG_SEED','MDNS'));
ALTER TABLE telecom_gateways ADD COLUMN IF NOT EXISTS discovered_at TIMESTAMP;

-- الرقم التسلسلي وإصدار البرنامج الثابت كما يقرأهما get_status.
-- المفتاح الفعلي لتمييز جهاز عن آخر حتى لو تغيّر عنوانه بـ DHCP.
ALTER TABLE telecom_gateways ADD COLUMN IF NOT EXISTS serial_number VARCHAR(80);
ALTER TABLE telecom_gateways ADD COLUMN IF NOT EXISTS firmware_version VARCHAR(80);
ALTER TABLE telecom_gateways ADD COLUMN IF NOT EXISTS mac_address VARCHAR(32);

CREATE UNIQUE INDEX IF NOT EXISTS idx_gateways_serial
    ON telecom_gateways(serial_number) WHERE serial_number IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_gateways_routing
    ON telecom_gateways(enabled, health_state, routing_priority);

-- ── لقطات المنافذ: الحقول التي تصحّح تفسير الإشارة ──────────────────
-- كان signal_percent وحده، وكان يُحسب من قراءة خام مغلوطة (99 ⇒ 100%).
-- نضيف dBm الفعلي وعلامة الصلاحية حتى يستطيع الموزّع استبعاد المنافذ
-- التي لا تحمل شبكة أصلًا.
ALTER TABLE gateway_port_snapshots ADD COLUMN IF NOT EXISTS signal_dbm INTEGER
    CHECK (signal_dbm IS NULL OR signal_dbm BETWEEN -140 AND 0);
ALTER TABLE gateway_port_snapshots ADD COLUMN IF NOT EXISTS signal_usable BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE gateway_port_snapshots ADD COLUMN IF NOT EXISTS operator_name VARCHAR(60);

-- signal_percent صار يقبل NULL: «لا قياس» تختلف عن «صفر بالمئة».
ALTER TABLE gateway_port_snapshots ALTER COLUMN signal_percent DROP NOT NULL;

-- ── توجيه المكالمات عبر الأسطول ─────────────────────────────────────
-- سجل اختيار المنفذ لكل مكالمة: يمكّن من تدقيق سبب اختيار بوابة بعينها
-- ومن حساب معدلات النجاح لكل جهاز.
CREATE TABLE IF NOT EXISTS gateway_route_decisions (
    id UUID PRIMARY KEY,
    gateway_id UUID REFERENCES telecom_gateways(id) ON DELETE SET NULL,
    port_index INTEGER,
    destination_prefix VARCHAR(8),
    matched_operator VARCHAR(40),
    score DOUBLE PRECISION,
    reason VARCHAR(200),
    outcome VARCHAR(20) NOT NULL DEFAULT 'SELECTED'
        CHECK (outcome IN ('SELECTED','REJECTED_NO_SIGNAL','REJECTED_BUSY','REJECTED_OFFLINE','FALLBACK')),
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_route_decisions_created ON gateway_route_decisions(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_route_decisions_gateway ON gateway_route_decisions(gateway_id, created_at DESC);

-- ===== Snapshot of V24__Younes_Id_Five_Digits.sql (fresh install only) =====
-- ═══════════════════════════════════════════════════════════════
-- V24 — معرّف يونس: الانتقال إلى خمسة أرقام
-- ═══════════════════════════════════════════════════════════════
--
-- الصيغة السابقة: YNS-XXXX-XXXX (أبجدية 32 رمزًا، ‎32^8 ≈ 1.1×10^12).
-- الصيغة الجديدة: 10001..99999 (خمسة أرقام، 89,999 معرّفًا).
-- القيمة 10000 محجوزة لمُرسِل رسائل النظام (RedIdGenerator.SYSTEM_ID)
-- ولا تُخصَّص لأي مستخدم، وإلا نُسبت رسائل الخادم إليه.
--
-- ## لماذا الترحيل لا إعادة التوليد العشوائي
--
-- المعرّف يظهر في `groups.created_by_red_id` وفي سجلات المكالمات وفي
-- جهات الاتصال المحفوظة على أجهزة المستخدمين. إعادة توليد عشوائية
-- تقطع هذه الروابط بصمت. الترحيل هنا **يحفظ الخريطة** في جدول
-- `red_id_migration_map` فيبقى أثر التحويل قابلًا للتدقيق والرجوع.
--
-- ## القيد الحرج
--
-- الفضاء الجديد 90,000 فقط. إن تجاوز عدد المستخدمين ذلك تفشل الهجرة
-- صراحةً بدل أن تُنتج معرّفات مكررة أو مبتورة.

-- ── 1. التحقق من السعة قبل أي تعديل ─────────────────────────────
DO $$
DECLARE
    user_count BIGINT;
BEGIN
    SELECT COUNT(*) INTO user_count FROM users;
    IF user_count > 90000 THEN
        RAISE EXCEPTION
            'تعذّر الترحيل: % مستخدمًا يتجاوز سعة الصيغة الخماسية (90000)',
            user_count;
    END IF;
END $$;

-- ── 2. جدول خريطة التحويل (للتدقيق والرجوع) ─────────────────────
CREATE TABLE IF NOT EXISTS red_id_migration_map (
    user_id      UUID PRIMARY KEY,
    old_red_id   VARCHAR(32) NOT NULL,
    new_red_id   VARCHAR(5)  NOT NULL,
    migrated_at  TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_red_id_map_new UNIQUE (new_red_id)
);

COMMENT ON TABLE red_id_migration_map IS
    'خريطة تحويل معرّف يونس من YNS-XXXX-XXXX إلى خمسة أرقام (V24)';

-- ── 3. تخصيص المعرّفات الجديدة ──────────────────────────────────
-- الترتيب عشوائي (random()) لا حسب تاريخ التسجيل: الترتيب التسلسلي
-- يكشف أقدمية الحساب وحجم القاعدة، وهي بيانات لا داعي لتسريبها.
-- التخصيص من مجموعة الأرقام الحرة كاملةً يضمن عدم التصادم بالبناء
-- بدل الاعتماد على إعادة المحاولة.
INSERT INTO red_id_migration_map (user_id, old_red_id, new_red_id)
SELECT
    u.id,
    u.red_id,
    LPAD(candidate.n::TEXT, 5, '0')
FROM (
    SELECT id, red_id, ROW_NUMBER() OVER (ORDER BY random()) AS rn
    FROM users
    WHERE red_id !~ '^[1-9][0-9]{4}$'   -- ما لم يُحوَّل بعد
) u
JOIN (
    SELECT n, ROW_NUMBER() OVER (ORDER BY random()) AS rn
    FROM generate_series(10001, 99999) AS n
    WHERE n::TEXT NOT IN (SELECT red_id FROM users WHERE red_id ~ '^[1-9][0-9]{4}$')
) candidate ON candidate.rn = u.rn
ON CONFLICT (user_id) DO NOTHING;

-- ── 4. تطبيق التحويل على جدول المستخدمين ────────────────────────
UPDATE users u
SET red_id = m.new_red_id
FROM red_id_migration_map m
WHERE u.id = m.user_id AND u.red_id = m.old_red_id;

-- ── 5. تحديث المراجع في الجداول الأخرى ──────────────────────────
-- بلا هذه الخطوة تبقى المجموعات تشير إلى معرّف لم يعد موجودًا،
-- فيظهر منشئ المجموعة «غير معروف» في التطبيق.
UPDATE groups g
SET created_by_red_id = m.new_red_id
FROM red_id_migration_map m
WHERE g.created_by_red_id = m.old_red_id;

-- ── 6. فرض الصيغة على مستوى المخطط ──────────────────────────────
-- القيد يمنع إدخال صيغة قديمة مستقبلًا: التحقق في الشيفرة وحده
-- يُلتفّ عليه بأي إدخال مباشر أو خدمة جديدة تنسى التحقق.
ALTER TABLE users DROP CONSTRAINT IF EXISTS ck_users_red_id_format;
ALTER TABLE users
    ADD CONSTRAINT ck_users_red_id_format
    CHECK (red_id ~ '^[1-9][0-9]{4}$');

-- تضييق العمود: 32 حرفًا لم تعد مبرَّرة لخمسة أرقام
ALTER TABLE users ALTER COLUMN red_id TYPE VARCHAR(5);
ALTER TABLE groups ALTER COLUMN created_by_red_id TYPE VARCHAR(5);

-- ── 7. الفهارس ──────────────────────────────────────────────────
-- فهرس البادئة (varchar_pattern_ops) كان لبحث LIKE على صيغة طويلة.
-- مع خمسة أرقام يكفي فهرس المساواة، وهو أصغر وأسرع.
DROP INDEX IF EXISTS idx_users_red_id_prefix;
CREATE UNIQUE INDEX IF NOT EXISTS uq_users_red_id ON users (red_id);

COMMENT ON COLUMN users.red_id IS
    'معرّف يونس: خمسة أرقام 10001-99999 (10000 محجوز للنظام). معرّف عرض عام لا سرّ — '
    'الفضاء قابل للتعداد الكامل فالحماية بتحديد المعدل لا بالمعرّف.';

-- ===== Snapshot of V25__Dinstar_Enhancements.sql (fresh install only) =====
-- ═══════════════════════════════════════════════════════════════════
-- DINSTAR Enhancements — قوالب SMS + رسائل مجدوَلَة + تحكم بالمنافذ
-- ═══════════════════════════════════════════════════════════════════

-- ── قوالب الرسائل SMS ────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS sms_templates (
    id VARCHAR(36) PRIMARY KEY,
    name VARCHAR(120) NOT NULL,
    text TEXT NOT NULL,
    encoding VARCHAR(20) NOT NULL DEFAULT 'gsm-7bit',
    category VARCHAR(30) NOT NULL DEFAULT 'custom',
    variables_json TEXT NOT NULL DEFAULT '',
    usage_count INTEGER NOT NULL DEFAULT 0,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_sms_templates_category ON sms_templates(category);

-- ── رسائل SMS مجدوَلَة ──────────────────────────────────────────
CREATE TABLE IF NOT EXISTS scheduled_sms (
    id VARCHAR(36) PRIMARY KEY,
    template_id VARCHAR(36) REFERENCES sms_templates(id) ON DELETE SET NULL,
    recipients_json TEXT NOT NULL,
    gateway_host VARCHAR(255),
    variables_json TEXT NOT NULL DEFAULT '{}',
    scheduled_at TIMESTAMP NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'PENDING'
        CHECK (status IN ('PENDING','SENT','DELIVERED','FAILED','CANCELLED')),
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    sent_at TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_scheduled_sms_status ON scheduled_sms(status);
CREATE INDEX IF NOT EXISTS idx_scheduled_sms_scheduled_at ON scheduled_sms(scheduled_at);

-- ── حالة التحكم بالمنافذ (طاقة + تحويل) ─────────────────────────
CREATE TABLE IF NOT EXISTS port_control_state (
    gateway_id UUID NOT NULL REFERENCES telecom_gateways(id) ON DELETE CASCADE,
    port_index INTEGER NOT NULL CHECK (port_index BETWEEN 0 AND 31),
    power_state BOOLEAN NOT NULL DEFAULT TRUE,
    call_forward_state VARCHAR(30) NOT NULL DEFAULT 'NONE',
    call_forward_number VARCHAR(20),
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (gateway_id, port_index)
);

-- ===== Snapshot of V25_1__User_Avatar_And_Bio.sql (fresh install only) =====
-- V25: إضافة عمود avatar_url و bio لجدول users — دعم شاشة البروفايل
-- avatar_url: مفتاح الوسائط المشفّر (objectKey) للصورة المعروضة في الدردشات والقوائم
-- bio: نص تعريفي قصير يعرضه المستخدم في برفايله (اختياري)

ALTER TABLE users ADD COLUMN IF NOT EXISTS avatar_url VARCHAR(255);
ALTER TABLE users ADD COLUMN IF NOT EXISTS bio VARCHAR(280);

-- ===== Snapshot of V26__Complete_Missing_Features_And_Fix_Build.sql (fresh install only) =====
-- ══════════════════════════════════════════════════════════════════
-- V26: إكمال الميزات الناقصة وإصلاح مشاكل البناء
-- Complete Missing Features & Fix Build Issues
-- ══════════════════════════════════════════════════════════════════
-- يغطي كل الفجوات المكتشفة في الخريطة التنافسية والتقرير الشامل:
-- 1. تثبيت الرسائل (Pin) 2. سجل التعديلات (Edit History) 3. القنوات/البث 4. ملاحظة لنفسي 5. فهارس ناقصة 6. إصلاحات Hibernate validate
-- ══════════════════════════════════════════════════════════════════

-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
-- 1. تثبيت الرسائل — pinned_messages
-- يسمح بتثبيت رسالة في محادثة أو مجموعة أو قناة (مثل واتساب/تيليجرام)
-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
CREATE TABLE IF NOT EXISTS pinned_messages (
    id UUID PRIMARY KEY,
    -- النطاق: محادثة خاصة أو مجموعة أو قناة
    conversation_id VARCHAR(128),          -- للرسائل الخاصة (Mongo conversationId)
    group_id UUID REFERENCES groups(id) ON DELETE CASCADE,
    channel_id UUID,                        -- يُربط بجدول channels أدناه
    -- الرسالة المثبتة
    message_uuid VARCHAR(40) NOT NULL,      -- مرجع إلى MongoDB messages.uuid / group_messages.uuid
    message_type VARCHAR(20) NOT NULL DEFAULT 'PRIVATE', -- PRIVATE, GROUP, CHANNEL
    -- من ثبتها
    pinned_by UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    pinned_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    -- انتهاء التثبيت (اختياري)
    expires_at TIMESTAMP,
    -- ترتيب التثبيت
    display_order INTEGER NOT NULL DEFAULT 0,
    CONSTRAINT pinned_scope_check CHECK (
        (conversation_id IS NOT NULL AND group_id IS NULL AND channel_id IS NULL) OR
        (conversation_id IS NULL AND group_id IS NOT NULL AND channel_id IS NULL) OR
        (conversation_id IS NULL AND group_id IS NULL AND channel_id IS NOT NULL)
    ),
    CONSTRAINT pinned_type_check CHECK (message_type IN ('PRIVATE','GROUP','CHANNEL'))
);
CREATE INDEX IF NOT EXISTS idx_pinned_conversation ON pinned_messages(conversation_id, pinned_at DESC) WHERE conversation_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_pinned_group ON pinned_messages(group_id, pinned_at DESC) WHERE group_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_pinned_channel ON pinned_messages(channel_id, pinned_at DESC) WHERE channel_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_pinned_expires ON pinned_messages(expires_at) WHERE expires_at IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uq_pinned_message ON pinned_messages(message_uuid, COALESCE(conversation_id, group_id::text, channel_id::text));

COMMENT ON TABLE pinned_messages IS 'الرسائل المثبتة في المحادثات والمجموعات والقنوات';

-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
-- 2. سجل تعديلات الرسائل — message_edit_history
-- يحفظ كل نسخة قبل التعديل للتدقيق والتراجع (E2EE: النص المشفر فقط)
-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
CREATE TABLE IF NOT EXISTS message_edit_history (
    id UUID PRIMARY KEY,
    message_uuid VARCHAR(40) NOT NULL,
    conversation_id VARCHAR(128),
    group_id UUID REFERENCES groups(id) ON DELETE CASCADE,
    editor_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    -- المحتوى المشفر قبل التعديل (payload المشفر، ليس plaintext)
    previous_payload BYTEA,
    previous_edited_at TIMESTAMP,
    edited_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    edit_reason VARCHAR(200),
    -- ترتيب التعديل
    edit_version INTEGER NOT NULL DEFAULT 1
);
CREATE INDEX IF NOT EXISTS idx_edit_history_message ON message_edit_history(message_uuid, edited_at DESC);
CREATE INDEX IF NOT EXISTS idx_edit_history_editor ON message_edit_history(editor_id, edited_at DESC);
CREATE INDEX IF NOT EXISTS idx_edit_history_conversation ON message_edit_history(conversation_id, edited_at DESC) WHERE conversation_id IS NOT NULL;

COMMENT ON TABLE message_edit_history IS 'سجل تعديلات الرسائل — يحفظ الحمولة المشفرة قبل كل تعديل';

-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
-- 3. القنوات / البث الأحادي — channels (مثل تيليجرام/واتساب)
-- قناة: ناشر واحد أو عدة ناشرين، جمهور كبير، رسائل أحادية الاتجاه
-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
CREATE TABLE IF NOT EXISTS channels (
    id UUID PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    username VARCHAR(40) UNIQUE,           -- @channel_username للبحث
    description TEXT,
    avatar_media_key VARCHAR(200),
    -- المالك والمشرفون
    owner_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    -- الخصوصية
    is_public BOOLEAN NOT NULL DEFAULT TRUE,
    is_verified BOOLEAN NOT NULL DEFAULT FALSE,
    -- الإحصائيات
    subscriber_count INTEGER NOT NULL DEFAULT 0,
    message_count INTEGER NOT NULL DEFAULT 0,
    -- الإعدادات
    allow_comments BOOLEAN NOT NULL DEFAULT FALSE,
    allow_reactions BOOLEAN NOT NULL DEFAULT TRUE,
    allow_forwarding BOOLEAN NOT NULL DEFAULT TRUE,
    slow_mode_seconds INTEGER NOT NULL DEFAULT 0,
    -- الحالة
    is_archived BOOLEAN NOT NULL DEFAULT FALSE,
    archived_at TIMESTAMP,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT channels_name_check CHECK (LENGTH(name) BETWEEN 2 AND 100),
    CONSTRAINT channels_slowmode_check CHECK (slow_mode_seconds BETWEEN 0 AND 3600)
);
CREATE INDEX IF NOT EXISTS idx_channels_owner ON channels(owner_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_channels_username ON channels(username) WHERE username IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_channels_public ON channels(is_public, subscriber_count DESC) WHERE is_public = TRUE AND is_archived = FALSE;
CREATE INDEX IF NOT EXISTS idx_channels_verified ON channels(is_verified, subscriber_count DESC) WHERE is_verified = TRUE;

CREATE TABLE IF NOT EXISTS channel_members (
    channel_id UUID NOT NULL REFERENCES channels(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    role VARCHAR(20) NOT NULL DEFAULT 'SUBSCRIBER', -- OWNER, ADMIN, MODERATOR, SUBSCRIBER
    is_muted BOOLEAN NOT NULL DEFAULT FALSE,
    is_banned BOOLEAN NOT NULL DEFAULT FALSE,
    joined_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_read_message_id VARCHAR(40),
    PRIMARY KEY (channel_id, user_id),
    CONSTRAINT channel_role_check CHECK (role IN ('OWNER','ADMIN','MODERATOR','SUBSCRIBER'))
);
CREATE INDEX IF NOT EXISTS idx_channel_members_user ON channel_members(user_id, joined_at DESC);
CREATE INDEX IF NOT EXISTS idx_channel_members_role ON channel_members(channel_id, role);

CREATE TABLE IF NOT EXISTS channel_invites (
    id UUID PRIMARY KEY,
    channel_id UUID NOT NULL REFERENCES channels(id) ON DELETE CASCADE,
    inviter_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    invite_code VARCHAR(20) UNIQUE NOT NULL,
    max_uses INTEGER,
    used_count INTEGER NOT NULL DEFAULT 0,
    expires_at TIMESTAMP,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT channel_invite_uses_check CHECK (max_uses IS NULL OR max_uses > 0)
);
CREATE INDEX IF NOT EXISTS idx_channel_invites_code ON channel_invites(invite_code);
CREATE INDEX IF NOT EXISTS idx_channel_invites_channel ON channel_invites(channel_id, created_at DESC);

COMMENT ON TABLE channels IS 'القنوات — بث أحادي الاتجاه لجمهور كبير';
COMMENT ON TABLE channel_members IS 'أعضاء القنوات واشتراكاتهم';
COMMENT ON TABLE channel_invites IS 'دعوات القنوات';

-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
-- 4. ملاحظة لنفسي — note_to_self
-- كل مستخدم له محادثة خاصة مع نفسه (conversationId = userId:self)
-- لا يحتاج جدول جديد، فقط السماح بذلك في التحقق + فهرس
-- لكن نضيف جدول تفضيلات سريع للوصول
-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
CREATE TABLE IF NOT EXISTS user_note_settings (
    user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    conversation_id VARCHAR(128) NOT NULL UNIQUE,
    is_pinned BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
COMMENT ON TABLE user_note_settings IS 'إعدادات محادثة ملاحظة لنفسي';

-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
-- 5. إعدادات الاختفاء المرن — disappearing_messages
-- يسمح بتوقيتات مرنة: 30 ثانية، 1 دقيقة، 5 دقائق، 1 ساعة، 1 يوم، 1 أسبوع، بعد القراءة
-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
CREATE TABLE IF NOT EXISTS disappearing_settings (
    id UUID PRIMARY KEY,
    -- النطاق
    conversation_id VARCHAR(128),
    group_id UUID REFERENCES groups(id) ON DELETE CASCADE,
    channel_id UUID REFERENCES channels(id) ON DELETE CASCADE,
    user_id UUID REFERENCES users(id) ON DELETE CASCADE, -- إعداد افتراضي للمستخدم
    -- التوقيت
    disappear_after_seconds INTEGER NOT NULL, -- 0 = معطل، 30، 60، 300، 3600، 86400، 604800، -1 = بعد القراءة
    mode VARCHAR(20) NOT NULL DEFAULT 'AFTER_SEND', -- AFTER_SEND, AFTER_READ
    enabled BOOLEAN NOT NULL DEFAULT TRUE,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by UUID REFERENCES users(id) ON DELETE SET NULL,
    CONSTRAINT disappear_seconds_check CHECK (disappear_after_seconds IN (0, 30, 60, 300, 900, 1800, 3600, 14400, 86400, 604800, -1)),
    CONSTRAINT disappear_mode_check CHECK (mode IN ('AFTER_SEND','AFTER_READ'))
);
CREATE INDEX IF NOT EXISTS idx_disappearing_conversation ON disappearing_settings(conversation_id) WHERE conversation_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_disappearing_group ON disappearing_settings(group_id) WHERE group_id IS NOT NULL;

COMMENT ON TABLE disappearing_settings IS 'إعدادات الرسائل ذاتية الاختفاء بتوقيتات مرنة';

-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
-- 6. إصلاحات Hibernate validate — أعمدة ناقصة أو أنواع غير متطابقة
-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

-- إصلاح طول red_id في كيان UserAccount: الكيان كان length=32 بينما DB صار VARCHAR(5) في V24
-- الحل: نضمن أن DB يقبل 32 لكن القيد يفرض 5 أرقام — نوسع العمود مؤقتًا ثم نضيق مع الحفاظ على القيد
-- (لا نلمس القيد ck_users_red_id_format الموجود، فقط نضمن عدم فشل validate بسبب الطول)
-- ملاحظة: لا نغير القيد، فقط نضمن أن العمود VARCHAR(32) ليطابق الكيان، والقيد يفرض 5 أرقام
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='users' AND column_name='red_id' AND character_maximum_length=5) THEN
        ALTER TABLE users ALTER COLUMN red_id TYPE VARCHAR(32);
        -- إعادة القيد بعد التوسيع
        ALTER TABLE users DROP CONSTRAINT IF EXISTS ck_users_red_id_format;
        ALTER TABLE users ADD CONSTRAINT ck_users_red_id_format CHECK (red_id ~ '^[1-9][0-9]{4}$');
    END IF;
END $$;

-- ضمان وجود عمود avatar_color (V19) و avatar_url/bio (V25) — قد تكون مفقودة في بيئات قديمة
ALTER TABLE users ADD COLUMN IF NOT EXISTS avatar_color VARCHAR(20);
ALTER TABLE users ADD COLUMN IF NOT EXISTS avatar_url VARCHAR(255);
ALTER TABLE users ADD COLUMN IF NOT EXISTS bio VARCHAR(280);
ALTER TABLE users ADD COLUMN IF NOT EXISTS theme_preference VARCHAR(30) NOT NULL DEFAULT 'SOVEREIGN_DARK';
ALTER TABLE users ADD COLUMN IF NOT EXISTS accent_color VARCHAR(20) NOT NULL DEFAULT 'CYAN';
ALTER TABLE users ADD COLUMN IF NOT EXISTS font_scale REAL NOT NULL DEFAULT 1.0;
ALTER TABLE users ADD COLUMN IF NOT EXISTS chat_bubble_style VARCHAR(20) NOT NULL DEFAULT 'ROUNDED';
ALTER TABLE users ADD COLUMN IF NOT EXISTS language VARCHAR(10) NOT NULL DEFAULT 'ar';
ALTER TABLE users ADD COLUMN IF NOT EXISTS is_rtl BOOLEAN NOT NULL DEFAULT TRUE;

-- إصلاح جدول saved_messages — قد يكون ناقصًا في بيئات قديمة (V20 أنشأه لكن IF NOT EXISTS قد فشل)
CREATE TABLE IF NOT EXISTS saved_messages (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    message_id UUID NOT NULL,
    saved_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    collection VARCHAR(50) NOT NULL DEFAULT 'DEFAULT',
    notes TEXT
);
CREATE INDEX IF NOT EXISTS idx_saved_messages_user ON saved_messages(user_id, saved_at DESC);

-- ضمان وجود جداول الملصقات (قد تفشل في V20 بسبب ترتيب الهجرات)
CREATE TABLE IF NOT EXISTS sticker_packs (
    id UUID PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    description TEXT,
    creator_id UUID REFERENCES users(id) ON DELETE SET NULL,
    is_official BOOLEAN NOT NULL DEFAULT FALSE,
    cover_media_key VARCHAR(200) NOT NULL,
    preview_media_key VARCHAR(200),
    sticker_count INTEGER NOT NULL DEFAULT 0,
    total_downloads INTEGER NOT NULL DEFAULT 0,
    is_free BOOLEAN NOT NULL DEFAULT TRUE,
    price_cents INTEGER NOT NULL DEFAULT 0,
    currency VARCHAR(3) NOT NULL DEFAULT 'USD',
    is_published BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS stickers (
    id UUID PRIMARY KEY,
    pack_id UUID NOT NULL REFERENCES sticker_packs(id) ON DELETE CASCADE,
    name VARCHAR(100),
    media_key VARCHAR(200) NOT NULL,
    emoji_tags TEXT[] DEFAULT '{}',
    display_order INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS user_sticker_packs (
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    pack_id UUID NOT NULL REFERENCES sticker_packs(id) ON DELETE CASCADE,
    installed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    is_favorite BOOLEAN NOT NULL DEFAULT FALSE,
    PRIMARY KEY (user_id, pack_id)
);

-- تفعيل امتداد pg_trgm للبحث التقريبي (يجب قبل فهارس gin_trgm_ops)
