-- ═══════════════════════════════════════════════════════════════════
-- Views للتقارير
-- ═══════════════════════════════════════════════════════════════════

-- عرض المكالمات الأخيرة
CREATE OR REPLACE VIEW v_dinstar_recent_calls AS
SELECT
    c.id,
    g.name as gateway_name,
    g.host as gateway_host,
    c.port_index,
    c.start_time,
    c.duration_seconds AS duration,
    c.caller_number,
    c.callee_number,
    c.direction,
    c.call_type,
    c.status AS hangup_cause,
    CASE
        WHEN c.direction = 'INBOUND' THEN c.caller_number
        ELSE c.callee_number
    END as contact_number
FROM dinstar_cdr c
JOIN telecom_gateways g ON g.id = c.gateway_id
ORDER BY c.start_time DESC
LIMIT 100;

-- عرض إحصائيات البوابات
CREATE OR REPLACE VIEW v_dinstar_gateway_stats AS
SELECT
    g.id,
    g.name,
    g.host,
    g.model,
    g.enabled,
    g.health_state,
    COUNT(DISTINCT c.id) as total_calls,
    COUNT(DISTINCT s.id) as total_sms,
    COUNT(DISTINCT u.id) as total_ussd,
    AVG(c.duration_seconds) as avg_call_duration,
    MAX(c.start_time) as last_call_at
FROM telecom_gateways g
LEFT JOIN dinstar_cdr c ON c.gateway_id = g.id
LEFT JOIN dinstar_sms_log s ON s.gateway_id = g.id
LEFT JOIN dinstar_ussd_log u ON u.gateway_id = g.id
WHERE g.vendor = 'DINSTAR'
GROUP BY g.id, g.name, g.host, g.model, g.enabled, g.health_state;

-- عرض التنبيهات غير المعترف بها
CREATE OR REPLACE VIEW v_dinstar_active_alerts AS
SELECT
    a.id,
    g.name as gateway_name,
    a.alert_type,
    a.severity,
    a.message,
    a.port_index,
    a.created_at,
    EXTRACT(EPOCH FROM (NOW() - a.created_at))/3600 as hours_since_alert
FROM dinstar_alerts a
JOIN telecom_gateways g ON g.id = a.gateway_id
WHERE a.acknowledged = FALSE
ORDER BY
    CASE a.severity
        WHEN 'CRITICAL' THEN 1
        WHEN 'WARNING' THEN 2
        ELSE 3
    END,
    a.created_at DESC;

-- ===== Snapshot of V27__Operational_Retention_Indexes.sql (fresh install only) =====
-- Retention scheduler selects oldest rows in bounded batches.
-- These time indexes keep operational cleanup and range dashboards scalable.
CREATE INDEX IF NOT EXISTS idx_admin_audit_retention_created ON admin_audit_log(created_at ASC);
CREATE INDEX IF NOT EXISTS idx_dinstar_cdr_retention_start ON dinstar_cdr(start_time ASC);
CREATE INDEX IF NOT EXISTS idx_system_health_retention_checked ON system_health(last_check_at ASC);

COMMENT ON INDEX idx_admin_audit_retention_created IS 'Bounded retention batch selection';
COMMENT ON INDEX idx_dinstar_cdr_retention_start IS 'Bounded CDR retention batch selection';
COMMENT ON INDEX idx_system_health_retention_checked IS 'Bounded health retention batch selection';

