-- ===== Snapshot of V31__Contact_Request_Outgoing_And_Cancellation.sql (fresh install only) =====
-- كانت هذه الهجرة V30 في فرع main، وV30 آخر (فهارس الأداء السيادية)
-- في هذا الفرع؛ فلمّا التقى الفرعان صار للإصدار الواحد ملفّان، وFlyway
-- يرفض الإقلاع عند تكرار الإصدار فيسقط الخادم كلّه عند بدء التشغيل.
-- رُقّيت هذه إلى V31 لأنها الأحدث زمنيًّا: أما V30 الأخرى فأقدم وقد
-- تكون طُبّقت في بيئات قائمة، وتغيير رقم هجرة مطبَّقة يفسد سجل Flyway.
-- طلبات الصداقة: إتاحة الإلغاء مع الاحتفاظ بسجل قرار واضح.
ALTER TABLE contact_requests
    DROP CONSTRAINT IF EXISTS contact_requests_status_check;

ALTER TABLE contact_requests
    ADD CONSTRAINT contact_requests_status_check
    CHECK (status IN ('PENDING', 'ACCEPTED', 'REJECTED', 'CANCELED'));

CREATE INDEX IF NOT EXISTS idx_contact_requests_requester_status
    ON contact_requests(requester_id, status, created_at DESC);

-- ===== Snapshot of V31_1__Legendary_Operational_Hardening.sql (fresh install only) =====
-- ══════════════════════════════════════════════════════════════════
-- V29: Legendary Operational Hardening & Final Polish
-- PostgreSQL — تحسين الأداء، سياسات الاستبقاء، والتنظيف التلقائي
-- ══════════════════════════════════════════════════════════════════

-- ━━━━ System Retention Config ━━━━
-- ضبط مدة الاحتفاظ بالبيانات التشغيلية لضمان استقرار الأداء
INSERT INTO system_settings(setting_key, setting_value) VALUES
    ('retention.audit_days', '90'),
    ('retention.health_days', '7'),
    ('retention.deleted_messages_days', '30'),
    ('retention.stale_sessions_days', '7')
ON CONFLICT (setting_key) DO UPDATE SET setting_value = EXCLUDED.setting_value;

-- ━━━━ Optimization Indexes ━━━━
-- تسريع البحث في السجلات الكبيرة
CREATE INDEX IF NOT EXISTS idx_users_last_seen ON users(last_seen DESC) WHERE status = 'APPROVED';
CREATE INDEX IF NOT EXISTS idx_admin_sessions_cleanup ON admin_sessions(expires_at) WHERE is_active = TRUE;

-- ━━━━ Automatic Retention Cleanup Function ━━━━
-- دالة مركزية لتنظيف البيانات القديمة بناءً على الإعدادات
CREATE OR REPLACE FUNCTION legendary_retention_cleanup() RETURNS VOID AS $$
DECLARE
    v_audit_days INTERVAL;
    v_health_days INTERVAL;
BEGIN
    -- جلب القيم من الإعدادات مع fallback
    SELECT (COALESCE(setting_value, '90') || ' days')::INTERVAL INTO v_audit_days FROM system_settings WHERE setting_key='retention.audit_days';
    SELECT (COALESCE(setting_value, '7') || ' days')::INTERVAL INTO v_health_days FROM system_settings WHERE setting_key='retention.health_days';

    -- التنظيف الفعلي
    DELETE FROM admin_audit_log WHERE created_at < NOW() - v_audit_days;
    DELETE FROM system_health WHERE last_check_at < NOW() - v_health_days;

    -- تنظيف الجلسات المنتهية (soft-delete)
    UPDATE admin_sessions SET is_active = FALSE, terminated_at = NOW(), termination_reason = 'RETENTION_CLEANUP'
    WHERE is_active = TRUE AND expires_at < NOW() - INTERVAL '1 day';
END;
$$ LANGUAGE plpgsql;

-- ━━━━ Final Branding Polish ━━━━
-- التأكد من وجود الهوية السيادية في كل مكان
UPDATE system_settings SET setting_value = 'YOUNES Sovereign Platform - Legendary Version' WHERE setting_key = 'brand.name.full';
INSERT INTO system_settings(setting_key, setting_value) VALUES ('brand.version', '1.0.0-legendary') ON CONFLICT (setting_key) DO UPDATE SET setting_value = EXCLUDED.setting_value;

COMMENT ON FUNCTION legendary_retention_cleanup IS 'Legendary: Automatic cleanup of operational data based on sovereign policy';

-- ===== Snapshot of V32__Schema_Corrections_And_Hardening.sql (fresh install only) =====
-- ══════════════════════════════════════════════════════════════════
-- V32: Comprehensive Schema Corrections & Hardening
-- PostgreSQL — تصحيحات شاملة لعيوب مكتشفة في التدقيق (DB audit)
-- V1..V31 لم تُلمس إطلاقاً (checksums محفوظة) — كل الإصلاحات هنا
-- ══════════════════════════════════════════════════════════════════

-- ━━━━ 1. saved_messages.message_id: UUID → VARCHAR(40) ━━━━
-- الخطأ: V20 عرّف message_id كـ UUID بينما معرفات الرسائل الحقيقية نصوص
-- (UuidV7 من MongoDB، مثل message_delivery_receipts.message_uuid VARCHAR(40)).
-- الإدراج الفعلي من كود الحفظ كان سيفشل أو يخزّن قيماً لا تطابق أي رسالة.
ALTER TABLE saved_messages ALTER COLUMN message_id TYPE VARCHAR(40);
COMMENT ON COLUMN saved_messages.message_id IS
    'معرف الرسالة النصي (UuidV7 من MongoDB) — يطابق message_delivery_receipts.message_uuid';
-- فهرس جزئي على المعرف النصي للمسح السريع عند إلغاء الحفظ
CREATE INDEX IF NOT EXISTS idx_saved_messages_message_id ON saved_messages(message_id);

-- ━━━━ 2. contact_requests: UNIQUE كامل → فهرس جزئي PENDING ━━━━
-- الخطأ: uq_contact_request_direction UNIQUE(requester_id, recipient_id) كان
-- يمنع إعادة إرسال طلب الصداقة للأبد بعد REJECTED/ACCEPTED.
-- الحل: التفرد يطبَّق على الطلبات النشطة فقط (PENDING).
ALTER TABLE contact_requests DROP CONSTRAINT IF EXISTS uq_contact_request_direction;
CREATE UNIQUE INDEX IF NOT EXISTS uq_contact_request_pending
    ON contact_requests(requester_id, recipient_id) WHERE status = 'PENDING';
COMMENT ON INDEX uq_contact_request_pending IS
    'يمنع ازدواج طلب صداقة نشط بين زوج واحد فقط — يسمح بإعادة الطلب بعد الحل';

-- ━━━━ 3. فهرس مكرر: إزالة idx_messages_delivery_receipts_message ━━━━
-- V15 أنشأ idx_delivery_receipts_message(message_uuid) و V26 كرّره باسم آخر.
-- الإبقاء على الاسم الأصلي فقط.
DROP INDEX IF EXISTS idx_messages_delivery_receipts_message;

-- ━━━━ 4. تحصين دالة الاستبقاء ضد NULL (عيب V31) ━━━━
-- الخطأ: SELECT (COALESCE(setting_value,'90') || ' days') INTO ... — عند غياب
-- صف الإعداد يبقى المتغير NULL (COALESCE لا يعمل بلا صف) فيصبح
-- DELETE ... WHERE created_at < NOW() - NULL → حذف كل شيء.
-- الحل: COALESCE على استعلام فرعي يضمن صفاً دائماً.
CREATE OR REPLACE FUNCTION legendary_retention_cleanup() RETURNS VOID AS $$
DECLARE
    v_audit_days INTERVAL;
    v_health_days INTERVAL;
BEGIN
    SELECT (COALESCE((SELECT setting_value FROM system_settings WHERE setting_key='retention.audit_days'), '90') || ' days')::INTERVAL INTO v_audit_days;
    SELECT (COALESCE((SELECT setting_value FROM system_settings WHERE setting_key='retention.health_days'), '7') || ' days')::INTERVAL INTO v_health_days;

    -- حارس إضافي: لا تنظيف أبداً بفاصل NULL أو سالب
    IF v_audit_days IS NULL OR v_audit_days < INTERVAL '1 day' THEN v_audit_days := INTERVAL '90 days'; END IF;
    IF v_health_days IS NULL OR v_health_days < INTERVAL '1 day' THEN v_health_days := INTERVAL '7 days'; END IF;

    DELETE FROM admin_audit_log WHERE created_at < NOW() - v_audit_days;
    DELETE FROM system_health WHERE last_check_at < NOW() - v_health_days;

    UPDATE admin_sessions SET is_active = FALSE, terminated_at = NOW(), termination_reason = 'RETENTION_CLEANUP'
    WHERE is_active = TRUE AND expires_at < NOW() - INTERVAL '1 day';
END;
$$ LANGUAGE plpgsql;

-- ━━━━ 5. brand.name.full: ضمان الوجود (عيب V31: UPDATE بلا INSERT) ━━━━
INSERT INTO system_settings(setting_key, setting_value)
VALUES ('brand.name.full', 'YOUNES Sovereign Platform - Legendary Version')
ON CONFLICT (setting_key) DO UPDATE SET setting_value = EXCLUDED.setting_value;

-- ━━━━ 6. توثيق قرارات مُدرَسة (بلا تغيير) ━━━━
-- • call_history (V14): ON DELETE CASCADE على caller_id/callee_id — قرار خصوصية
--   مقصود: حذف الحساب يمسح سجل مكالماته. لا تغيير.
-- • user_reports: يحتوي reported_id (V10) وtarget_user_id (V19) — entity الحالية
--   (UserReport) تستخدم target_user_id فقط؛ reported_id عمود قديم غير مستخدم.
--   محفوظ لتوافق البيانات التاريخية؛ يُحذف في ترقية لاحقة بعد تأكيد عدم استخدامه.
-- • stories (Mongo): expiresAt ليست TTL عمداً — StoryService.cleanupExpired()
--   المجدولة كل 5 دقائق تمسح الميديا من MinIO قبل حذف المستندات؛ TTL كانت
--   تحذف المستند أولاً فتسرّب الملفات. قرار مقصود.

-- ===== Snapshot of V33__Sms_Messages.sql (fresh install only) =====
-- V33__Sms_Messages.sql
-- مخطط جداول الرسائل النصية (SMS) وعلامات القراءة للمحادثات.
-- يُستَخدم من قبَاطع Twilio/DINSTAR لتخزين الرسائل الواردة والصادرة
-- مع حالة التسليم (queued/sent/delivered/failed) وعدّاد المحاولات.
-- owner_id يشير إلى users(id) ويُمسح عند حذف المستخدم (ON DELETE CASCADE).

CREATE TABLE IF NOT EXISTS sms_messages (
    id UUID PRIMARY KEY,
    owner_id UUID REFERENCES users(id) ON DELETE CASCADE,
    number VARCHAR(20) NOT NULL,
    content TEXT NOT NULL,
    direction VARCHAR(4) NOT NULL,
    status VARCHAR(12) NOT NULL,
    port INTEGER,
    gateway_id UUID,
    sms_parts INTEGER NOT NULL DEFAULT 1,
    error_text VARCHAR(255),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    sent_at TIMESTAMPTZ,
    delivered_at TIMESTAMPTZ,
    read_at TIMESTAMPTZ
);

CREATE INDEX IF NOT EXISTS idx_sms_owner_created ON sms_messages(owner_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_sms_number_created ON sms_messages(number, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_sms_status ON sms_messages(status, created_at DESC);

-- علامة قراءة لكل محادثة (user_id, number) → آخر رسالة مقروءة فيها.
CREATE TABLE IF NOT EXISTS sms_conversation_read (
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    number VARCHAR(20) NOT NULL,
    last_read_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (user_id, number)
);

-- ===== Snapshot of V34__Pstn_Permanent_Sim_Binding.sql (fresh install only) =====
-- ═══════════════════════════════════════════════════════════════════════════
-- V34: الربط الدائم 1:1 — حساب ↔ شريحة GSM ثابتة
-- كل حساب يملك شريحة دائمة على بوابة/منفذ محدد (16 منفذ = 8G + 8T)
-- ═══════════════════════════════════════════════════════════════════════════

-- ربط الحساب ببوابة ومنفذ محدد (شريحة دائمة)
ALTER TABLE users
    ADD COLUMN IF NOT EXISTS pstn_gateway_id UUID REFERENCES telecom_gateways(id) ON DELETE SET NULL,
    ADD COLUMN IF NOT EXISTS pstn_port_index INT,
    ADD COLUMN IF NOT EXISTS pstn_number VARCHAR(20);

-- قيد: المنفذ 0..31 (8G=0..7, 8T=0..7 لكن مع بوابتين = 16 منفذ فعلي)
ALTER TABLE users
    ADD CONSTRAINT chk_users_pstn_port_range
        CHECK (pstn_port_index IS NULL OR pstn_port_index BETWEEN 0 AND 31);

-- قيد: الاتساق — إما الكل NULL أو الكل NOT NULL
ALTER TABLE users
    ADD CONSTRAINT chk_users_pstn_binding_consistency
        CHECK (
            (pstn_gateway_id IS NULL AND pstn_port_index IS NULL AND pstn_number IS NULL)
         OR (pstn_gateway_id IS NOT NULL AND pstn_port_index IS NOT NULL AND pstn_number IS NOT NULL)
        );

-- كل شريحة تخدم حساباً واحداً فقط — منع ازدواج الربط
ALTER TABLE users
    ADD CONSTRAINT uq_users_pstn_port UNIQUE (pstn_gateway_id, pstn_port_index);

-- فهارس للبحث السريع (الوارد: number → owner, والصادر: gateway+port → owner)
CREATE INDEX IF NOT EXISTS idx_users_pstn_number ON users(pstn_number) WHERE pstn_number IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_users_pstn_gateway_port ON users(pstn_gateway_id, pstn_port_index) WHERE pstn_gateway_id IS NOT NULL;

-- تعليقات للتوثيق
COMMENT ON COLUMN users.pstn_gateway_id IS 'البوابة المالكة للشريحة الدائمة (FK telecom_gateways.id)';
COMMENT ON COLUMN users.pstn_port_index IS 'منفذ الشريحة 0..7 على البوابة (0=المنفذ الأول)';
COMMENT ON COLUMN users.pstn_number IS 'رقم الشريحة الحقيقي (مثل 774xxxxxx) يظهر للمستلم الخارجي';

