-- ===== Snapshot of V38__Pstn_Number_Unique_And_Reconcile.sql (fresh install only) =====
-- ═══════════════════════════════════════════════════════════════════════════
-- V35: PSTN number global uniqueness + reconcile transparency
-- Prevents duplicate CLIP / inbound ambiguity: the same MSISDN must not
-- be bound to two different RED accounts (would route inbound to wrong user).
-- Partial index allows multiple unbound rows (pstn_number IS NULL).
-- ═══════════════════════════════════════════════════════════════════════════

-- Global unique number — two accounts must never share the same MSISDN.
-- IF NOT EXISTS keeps the migration idempotent on rerun.
CREATE UNIQUE INDEX IF NOT EXISTS ux_users_pstn_number
    ON users(pstn_number) WHERE pstn_number IS NOT NULL;

COMMENT ON INDEX ux_users_pstn_number IS 'Guarantees 1:1 MSISDN→account; prevents duplicate CLIP/inbound routing (V35 smart SIM→port discovery)';

-- Helper view for reconcile transparency: joins live snapshots with bindings.
-- Used by DinstarControl and reconcile endpoint for audit; shows per-port
-- live state vs bound RED account. No data change, read-only.
CREATE OR REPLACE VIEW v_pstn_reconcile AS
SELECT
    g.id                          AS gateway_id,
    g.host                        AS gateway_host,
    g.model                       AS gateway_model,
    g.enabled                     AS gateway_enabled,
    ps.port_index                 AS port_index,
    ps.radio_type                 AS radio_type,
    ps.registration_state         AS registration_state,
    ps.call_state                 AS call_state,
    ps.signal_raw                 AS signal_raw,
    ps.signal_dbm                 AS signal_dbm,
    ps.signal_percent             AS signal_percent,
    ps.signal_usable              AS signal_usable,
    ps.operator_name              AS operator_name,
    ps.gprs_state                 AS gprs_state,
    ps.sim_number_masked          AS live_number_masked,
    ps.imsi_masked                AS imsi_masked,
    ps.iccid_masked               AS iccid_masked,
    ps.observed_at                AS observed_at,
    u.id                          AS bound_user_id,
    u.red_id                      AS bound_red_id,
    u.username                    AS bound_username,
    u.pstn_number                 AS bound_number,
    CASE
        WHEN u.id IS NULL AND ps.signal_usable THEN 'UNBOUND_HAS_SIM'
        WHEN u.id IS NOT NULL AND ps.sim_number_masked IS NULL AND ps.signal_usable THEN 'NEEDS_NUMBER_LEARNING'
        WHEN u.id IS NOT NULL AND ps.signal_usable = false AND ps.sim_number_masked IS NULL THEN 'ORPHAN_BINDING_NEEDS_CLEAR'
        WHEN u.id IS NULL THEN 'EMPTY'
        ELSE 'BOUND'
    END AS reconcile_status
FROM telecom_gateways g
LEFT JOIN gateway_port_snapshots ps ON ps.gateway_id = g.id
LEFT JOIN users u ON u.pstn_gateway_id = g.id AND u.pstn_port_index = ps.port_index
WHERE g.vendor = 'DINSTAR';

COMMENT ON VIEW v_pstn_reconcile IS 'Live port snapshot vs permanent SIM binding (V35) — used by /api/admin/dinstar/bindings/reconcile for transparency';

-- ===== Snapshot of V39__Sms_Delivery_Correlation.sql (fresh install only) =====
-- V39__Sms_Delivery_Correlation.sql
-- ═══════════════════════════════════════════════════════════════════════
-- إصلاح مسار تتبّع الرسائل من الطرف إلى الطرف مع بوابة DINSTAR UC2000.
-- ═══════════════════════════════════════════════════════════════════════
--
-- ## العطل الذي تُعالجه هذه الترقية
--
-- واجهة UC2000 تربط الرسالة بتقرير تسليمها عبر مفتاحين لا ثالث لهما:
--
--   1. `user_id`  — عدد صحيح يُرسله العميل في `send_sms`، ويُعاد كما هو
--                   في `query_sms_result`. هو المفتاح الذي يعرّف «أي
--                   رسالة من رسائلي» في الرد.
--   2. `ref_id`   — مرجع تُصدره الشبكة، يظهر في `query_sms_result`، ثم
--                   يعود في `query_sms_deliver_status`. هو المفتاح الذي
--                   يُطابَق به تقرير التسليم.
--
-- الشيفرة السابقة لم تحفظ أيًّا منهما:
--
-- * `SmsService.send` كان يرسل `user_id = users.red_id` وهو **نص**
--   (مثل "RED-8F3A"). الحقل رقمي في الواجهة، فالبوابة ترفضه أو تُصفّره،
--   وبأي حال لا يعود في الرد فيستحيل معرفة صاحب النتيجة.
--
-- * تقرير التسليم كان يُطابَق **بالرقم**. رسالتان إلى الرقم نفسه في
--   دقيقة واحدة — وهو الشائع في OTP والتنبيهات — تخلطان تقريريهما،
--   فتُعلَّم رسالة فاشلة كأنها وصلت.
--
-- * `status_code` الرقمي (0 وصلت / 32-63 فشل مؤقت / 64-255 فشل دائم)
--   كان يُقرأ كأنه نص `status`. الحقل النصي غير موجود في هذا المسار،
--   فلم تنتقل أي رسالة من SENT إلى DELIVERED منذ كتابة الشيفرة.
--
-- * الرسائل الواردة كانت تُقرأ بلا `incoming_sms_id`، فيُعاد الصندوق
--   كاملًا كل 12 ثانية، وتُبنى إزالة التكرار على تشابه النص خلال
--   دقيقتين — حيلة تُسقط رسالتين متطابقتين حقيقيتين وتُبقي التكرار
--   إن تأخّرت الدورة.
--
-- ## ما تضيفه
--
-- أعمدة المطابقة على `sms_messages`، وجدول مؤشّر لكل بوابة يحفظ أعلى
-- `incoming_sms_id` عُلِم به، وحالتان جديدتان في دورة حياة الرسالة.

-- ─────────────────────────────────────────────────────────────────────
-- 1. أعمدة المطابقة
-- ─────────────────────────────────────────────────────────────────────

ALTER TABLE sms_messages
    -- المعرّف الرقمي المُرسل إلى البوابة في send_sms.param[].user_id.
    -- لا يُشتق من red_id: ذاك نص، وهذا يجب أن يكون عددًا فريدًا.
    ADD COLUMN IF NOT EXISTS dinstar_user_id BIGINT,

    -- مرجع الشبكة من query_sms_result — به يُطابَق تقرير التسليم.
    ADD COLUMN IF NOT EXISTS dinstar_ref_id BIGINT,

    -- معرّف مهمة الإرسال من رد send_sms، يلزم لإيقافها عبر stop_sms.
    ADD COLUMN IF NOT EXISTS dinstar_task_id BIGINT,

    -- المؤشّر التزايدي للرسالة الواردة — أساس القراءة بلا تكرار.
    ADD COLUMN IF NOT EXISTS incoming_sms_id BIGINT,

    -- الترميز الفعلي على السلك (gsm-7bit / unicode). كان يُحسب ثم
    -- يُنسى، فيستحيل تفسير لماذا انقسمت رسالة إلى أجزاء أكثر.
    ADD COLUMN IF NOT EXISTS encoding VARCHAR(12),

    -- status_code الخام كما ورد، محفوظًا للتشخيص بعد الترجمة.
    ADD COLUMN IF NOT EXISTS delivery_status_code INT,

    -- عدد الأجزاء التي أكّدت الشبكة نجاحها (succ_count مقابل count).
    ADD COLUMN IF NOT EXISTS parts_confirmed INT,

    -- IMSI الشريحة المُرسِلة — يُثبّت أي رقم ظهر للمستلم فعلًا.
    ADD COLUMN IF NOT EXISTS sender_imsi VARCHAR(32),

    -- آخر محاولة استعلام: يمنع إعادة الاستعلام عن الشيء نفسه كل دورة.
    ADD COLUMN IF NOT EXISTS last_polled_at TIMESTAMPTZ,

    -- عدد مرات إعادة الإرسال بعد فشل مؤقت (status_code 32..63).
    ADD COLUMN IF NOT EXISTS retry_count INT NOT NULL DEFAULT 0;

-- المطابقة تجري بهذين المفتاحين، فلا بد من فهرسة كل منهما.
CREATE INDEX IF NOT EXISTS idx_sms_dinstar_user_id
    ON sms_messages(dinstar_user_id) WHERE dinstar_user_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_sms_dinstar_ref_id
    ON sms_messages(dinstar_ref_id) WHERE dinstar_ref_id IS NOT NULL;

-- دورة الاستعلام تبحث عن الرسائل المعلّقة الأقدم استعلامًا.
CREATE INDEX IF NOT EXISTS idx_sms_pending_poll
    ON sms_messages(status, last_polled_at NULLS FIRST)
    WHERE direction = 'OUT' AND status IN ('QUEUED', 'SENT');

-- ─────────────────────────────────────────────────────────────────────
-- 2. منع تكرار الرسائل الواردة على مستوى قاعدة البيانات
-- ─────────────────────────────────────────────────────────────────────
--
-- المؤشّر التزايدي فريد لكل بوابة. القيد هنا هو الضمانة الأخيرة: حتى
-- إن تعطّل المؤشّر أو تسابقت دورتان، لا تُدرَج الرسالة نفسها مرتين.
-- الشرط الجزئي يستثني الصادر والرسائل القديمة التي لا تحمل مؤشّرًا.

CREATE UNIQUE INDEX IF NOT EXISTS uq_sms_incoming_per_gateway
    ON sms_messages(gateway_id, incoming_sms_id)
    WHERE direction = 'IN' AND incoming_sms_id IS NOT NULL;

-- ─────────────────────────────────────────────────────────────────────
-- 3. مؤشّر القراءة لكل بوابة
-- ─────────────────────────────────────────────────────────────────────
--
-- بدل قراءة الصندوق كاملًا كل دورة، يُحفَظ أعلى معرّف عُلِم به لكل
-- بوابة ويُمرَّر في الطلب التالي. هذا هو ما تتوقعه الواجهة أصلًا.

CREATE TABLE IF NOT EXISTS dinstar_sms_cursor (
    gateway_id          UUID PRIMARY KEY,

    -- أعلى incoming_sms_id تمّت معالجته بنجاح.
    last_incoming_id    BIGINT      NOT NULL DEFAULT 0,

    -- آخر مزامنة ناجحة — للتشخيص وقياس تأخّر الابتلاع.
    last_sync_at        TIMESTAMPTZ,

    -- عدد الدورات الفاشلة المتتالية. تُستخدم لكتم السجل ولفتح
    -- قاطع الدائرة بدل إغراق البوابة بمحاولات على جهاز ساقط.
    consecutive_failures INT        NOT NULL DEFAULT 0,

    last_error          VARCHAR(300),

    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT chk_sms_cursor_id_non_negative CHECK (last_incoming_id >= 0)
);

COMMENT ON TABLE dinstar_sms_cursor IS
    'مؤشّر القراءة التزايدية للرسائل الواردة لكل بوابة (incoming_sms_id).';

-- ─────────────────────────────────────────────────────────────────────
-- 3.b مُصدِر معرّفات user_id
-- ─────────────────────────────────────────────────────────────────────
--
-- `user_id` يجب أن يكون عددًا فريدًا **يبقى فريدًا بعد إعادة التشغيل**.
-- التوليد السابق كان `AtomicInteger` مُهيَّأً من `currentTimeMillis()`:
-- يفقد موضعه عند كل إقلاع، فقد يعيد إصدار معرّف لرسالة ما زالت معلّقة
-- في البوابة، فتُنسَب نتيجتها إلى الرسالة الخطأ.
--
-- التسلسل في قاعدة البيانات يحلّ ذلك: مركزي، ذرّي، ومستمر.
-- الحد الأعلى 2^31-1 يقارب حد `int` في الواجهة، والدورة تعيد من 1
-- بأمان لأن الرسائل القديمة تكون قد أُنجزت قبل استنفاد المدى.

CREATE SEQUENCE IF NOT EXISTS dinstar_sms_user_id_seq
    AS BIGINT
    START WITH 1
    INCREMENT BY 1
    MINVALUE 1
    MAXVALUE 2147483647
    CYCLE;

COMMENT ON SEQUENCE dinstar_sms_user_id_seq IS
    'مُصدِر send_sms.param[].user_id — فريد ومستمر عبر إعادة التشغيل.';

-- ─────────────────────────────────────────────────────────────────────
-- 4. توسيع دورة حياة الرسالة
-- ─────────────────────────────────────────────────────────────────────
--
-- كانت الحالات: PENDING, SENT, DELIVERED, FAILED, RECEIVED. وكان
-- `SENT` يُكتب بمجرد ردّ HTTP 2xx — أي حتى مع error_code = 550 (لا منفذ
-- متاح) أو 413 (تجاوز الحد). فيرى المستخدم «أُرسلت» ولم تُرسَل.
--
-- تُضاف حالتان تفصلان المراحل الثلاث فصلًا صحيحًا:
--   QUEUED    — البوابة قبلت الطلب (error_code 202) ولم تسلّمه للشبكة.
--   SENT      — الشبكة قبلته (query_sms_result: SENT_OK) ومعه ref_id.
--   DELIVERED — تقرير التسليم أكّد الوصول (status_code = 0).
--   RETRYING  — فشل مؤقت (32..63) وسيُعاد.
--
-- العمود VARCHAR(12) يتّسع لأطولها ("DELIVERED" = 9، "RETRYING" = 8).

ALTER TABLE sms_messages
    ALTER COLUMN status TYPE VARCHAR(12);

-- ─────────────────────────────────────────────────────────────────────
-- 5. تعليقات توثيقية على الأعمدة الحرجة
-- ─────────────────────────────────────────────────────────────────────

COMMENT ON COLUMN sms_messages.dinstar_user_id IS
    'المعرّف الرقمي في send_sms.param[].user_id — به تُطابَق نتيجة query_sms_result.';
COMMENT ON COLUMN sms_messages.dinstar_ref_id IS
    'مرجع الشبكة من query_sms_result — به يُطابَق query_sms_deliver_status.';
COMMENT ON COLUMN sms_messages.delivery_status_code IS
    'TP-Status الخام (3GPP TS 23.040 §9.2.3.15): 0 وصلت، 32-63 مؤقت، 64-255 دائم.';
COMMENT ON COLUMN sms_messages.incoming_sms_id IS
    'المؤشّر التزايدي من query_incoming_sms — فريد لكل بوابة.';

-- ===== Snapshot of V40__Cdr_Ingest_And_Scheduled_Sms_Alignment.sql (fresh install only) =====
-- V40__Cdr_Ingest_And_Scheduled_Sms_Alignment.sql
-- ═══════════════════════════════════════════════════════════════════════
-- محاذاة `dinstar_cdr` و`scheduled_sms` مع ما تكتبه الشيفرة فعلًا.
-- ═══════════════════════════════════════════════════════════════════════
--
-- ## كيف وقع العطل
--
-- `dinstar_cdr` أُنشئ في V15 بأعمدة: `duration_seconds` و`status`.
-- ثم كتب V26_1 تعريفًا ثانيًا للجدول نفسه بأعمدة مختلفة
-- (`duration`, `hangup_cause`, `codec`, `sip_call_id`, `asterisk_channel`,
-- `raw_data`) — لكنه `CREATE TABLE IF NOT EXISTS`، والجدول كان موجودًا،
-- فلم يُنفَّذ التعريف الثاني ولا سطر منه. بقي الجدول على شكل V15.
--
-- الشيفرة كُتبت على الشكل الثاني المتخيَّل:
--
--   * `CdrIngestScheduler.ingestFrom` تُدخل `duration, hangup_cause, codec,
--     raw_data` — أعمدة لا وجود لها. الإدراج يرفع
--     `column "duration" of relation "dinstar_cdr" does not exist`،
--     والاستثناء يُبتلَع في `catch` فوق الحلقة ويُسجَّل على مستوى DEBUG.
--     النتيجة: `dinstar_cdr` بقي فارغًا (0 صفوف) بلا أي أثر في السجل
--     العادي، مع أن المُجدول يعمل كل خمس دقائق منذ نشره.
--
--   * `DinstarApiService.saveCdrRecord` تُدخل الأعمدة نفسها + عمودين
--     آخرين، وتفشل بالمثل.
--
-- `scheduled_sms` أُنشئ في V25 بلا `error_text` ولا `updated_at`، بينما
-- `ScheduledSmsDispatcher` يكتبهما في مسار الفشل — أي أن تسجيل سبب فشل
-- رسالة مجدوَلة يفشل هو نفسه، فتبقى الرسالة على `PENDING` وتُعاد
-- محاولتها كل دقيقة أبدًا.
--
-- ## ما تفعله هذه الترقية
--
-- تُضيف الأعمدة التشخيصية الناقصة إلى الشكل القائم (لا تُعيد تسمية
-- `duration_seconds` ولا `status`: كلاهما مستخدم في V26_1 view وفي
-- سياسات الاحتفاظ، وإعادة التسمية تكسرهما). الشيفرة تُصحَّح لتكتب
-- الأسماء الحقيقية.

-- ─────────────────────────────────────────────────────────────────────
-- 1. أعمدة CDR التشخيصية
-- ─────────────────────────────────────────────────────────────────────

ALTER TABLE dinstar_cdr
    -- سبب الإنهاء النصي من `get_cdr.hangup` — يفسّر لماذا لم تُجَب.
    ADD COLUMN IF NOT EXISTS hangup_cause VARCHAR(50),

    -- ترميز الصوت المتفاوَض عليه (`codec`) — لتشخيص جودة المكالمة.
    ADD COLUMN IF NOT EXISTS codec VARCHAR(20),

    -- رمز إطلاق GSM من الشبكة (`gsm_code`) — كان يُحسب في الشيفرة ثم
    -- يُهمَل لعدم وجود عمود له.
    ADD COLUMN IF NOT EXISTS gsm_code INTEGER,

    -- قناة Asterisk ومعرّف SIP — يربطان سجل البوابة بسجل الوسيط.
    ADD COLUMN IF NOT EXISTS sip_call_id VARCHAR(100),
    ADD COLUMN IF NOT EXISTS asterisk_channel VARCHAR(100),

    -- الرد الخام كما ورد من الجهاز. يُحفظ لأن حقول `get_cdr` تتغيّر
    -- بين إصدارات البرنامج الثابت، فبلا الخام يستحيل التحقيق لاحقًا.
    ADD COLUMN IF NOT EXISTS raw_data JSONB;

COMMENT ON COLUMN dinstar_cdr.hangup_cause IS
    'حقل hangup من get_cdr — السبب النصي لإنهاء المكالمة.';
COMMENT ON COLUMN dinstar_cdr.gsm_code IS
    'حقل gsm_code من get_cdr — رمز إطلاق شبكة GSM.';
COMMENT ON COLUMN dinstar_cdr.raw_data IS
    'استجابة get_cdr الخام لهذا السجل — مرجع التحقيق عند تغيّر الحقول.';

-- ─────────────────────────────────────────────────────────────────────
-- 2. الحقول الإلزامية التي لا تملأها عملية الابتلاع
-- ─────────────────────────────────────────────────────────────────────
--
-- `id` من نوع UUID و`NOT NULL` بلا قيمة افتراضية، فكل إدراج كان
-- ملزَمًا بتوليده في التطبيق. إعطاؤه افتراضًا في قاعدة البيانات يجعل
-- الإدراج الجزئي (المسار الصحيح: عمود واحد لكل حقل معروف) ممكنًا
-- ويمنع تكرار منطق التوليد في كل موضع.

ALTER TABLE dinstar_cdr
    ALTER COLUMN id SET DEFAULT gen_random_uuid();

-- ─────────────────────────────────────────────────────────────────────
-- 3. منع تكرار سجلات CDR على مستوى قاعدة البيانات
-- ─────────────────────────────────────────────────────────────────────
--
-- كان المُجدول يفحص الوجود بـ`SELECT COUNT(*)` ثم يُدرج: نافذة سباق
-- مفتوحة بين الفحص والإدراج، ودورتان متزامنتان تُدرجان السجل مرتين.
-- المفتاح الطبيعي لسجل مكالمة على بوابة هو (البوابة، المنفذ، زمن
-- البدء، المتصل، المطلوب) — فيصير القيد هو الضمانة، ويصبح الإدراج
-- `ON CONFLICT DO NOTHING` بلا فحص مسبق.
--
-- الفهرس جزئي: السجلات القديمة قد تحمل NULL في هذه الحقول، و`UNIQUE`
-- على NULL لا يمنع التكرار أصلًا، فيُستثنى الناقص صراحةً.

CREATE UNIQUE INDEX IF NOT EXISTS uq_dinstar_cdr_natural_key
    ON dinstar_cdr(gateway_id, port_index, start_time, caller_number, callee_number)
    WHERE gateway_id IS NOT NULL
      AND port_index IS NOT NULL
      AND start_time IS NOT NULL;

-- ─────────────────────────────────────────────────────────────────────
-- 4. أعمدة تتبّع فشل الرسائل المجدوَلة
-- ─────────────────────────────────────────────────────────────────────

ALTER TABLE scheduled_sms
    -- سبب الفشل كما ورد من البوابة أو من الاستثناء. بلا هذا العمود كان
    -- تسجيل الفشل يفشل، فتبقى الرسالة PENDING وتُعاد كل دقيقة.
    ADD COLUMN IF NOT EXISTS error_text VARCHAR(300),

    ADD COLUMN IF NOT EXISTS updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP;

-- حالة RETRYING تلزم لتمييز «فشل مؤقت سيُعاد» من «فشل نهائي»، وهي
-- مستخدمة في دورة حياة sms_messages بعد V39 فتُوحَّد هنا أيضًا.
ALTER TABLE scheduled_sms
    DROP CONSTRAINT IF EXISTS scheduled_sms_status_check;

ALTER TABLE scheduled_sms
    ADD CONSTRAINT scheduled_sms_status_check
    CHECK (status IN ('PENDING','QUEUED','SENT','DELIVERED','FAILED','CANCELLED','RETRYING'));

COMMENT ON COLUMN scheduled_sms.error_text IS
    'سبب فشل آخر محاولة إرسال — كان يُكتب إلى عمود غير موجود.';

-- ===== Snapshot of V41__Cdr_Ring_Duration_Nullable.sql (fresh install only) =====
-- V41__Cdr_Ring_Duration_Nullable.sql
-- ═══════════════════════════════════════════════════════════════════════
-- `ring_duration_seconds` يقبل NULL: المكالمة غير المُجابة لا زمن رنين لها.
-- ═══════════════════════════════════════════════════════════════════════
--
-- ## ما كان معطوبًا
--
-- العمود مُعرَّف في V15 بـ`NOT NULL DEFAULT 0`، ولم يكن أيّ مُدرِج يكتبه —
-- فحمل الصفر في 110 صفًّا من 110. والصفر هنا ليس «غير معروف» بل جملةٌ خبرية:
-- «رَنَّ صفر ثانية»، أي أُجيبت لحظيًا. فيُقرأ سجل مكالمات كامل كأن كل نداء
-- أُجيب فورًا.
--
-- الطرفان اللازمان للحساب موجودان في كل صفّ (`start_time` و`answer_time`)،
-- فصار [DinstarApiContract.Cdr.ringSeconds] يشتقّه. لكن المكالمة غير المُجابة
-- بلا `answer_time` أصلًا، فزمن رنينها **مجهول** لا صفر: الجهاز لا يُصدر زمن
-- الإنهاء في `get_cdr`، فلا سبيل لمعرفة كم رَنَّ قبل أن يُقطع.
--
-- بقاء `NOT NULL DEFAULT 0` يُجبر المُدرِج على كتابة صفرٍ كاذب في كل مكالمة
-- غير مُجابة — وهو نفس العيب الذي نُصلحه. لذا يُرفَع القيد ويُزال الافتراضي:
-- NULL هو التمثيل الصادق للمجهول.
--
-- ## لماذا لا تُحدَّث الصفوف القائمة
--
-- الصفوف الـ110 الحالية كلها `answered` بـ`answer_time` غير فارغ، فقيمتها
-- الصحيحة محسوبة لا مجهولة — وتُصحَّح أدناه من طرفَيها بدل تركها صفرًا.
-- ما لا `answer_time` له يُترك NULL.

ALTER TABLE dinstar_cdr
    ALTER COLUMN ring_duration_seconds DROP DEFAULT,
    ALTER COLUMN ring_duration_seconds DROP NOT NULL;

COMMENT ON COLUMN dinstar_cdr.ring_duration_seconds IS
    'زمن الرنين بالثواني = answer_time - start_time. NULL للمكالمة غير المُجابة: '
    'الجهاز لا يُصدر زمن الإنهاء في get_cdr فزمن رنينها مجهول، والصفر يُقرأ «أُجيبت فورًا».';

-- تصحيح الصفوف التي يمكن حسابها: أُدرِجت قبل الاشتقاق فحملت افتراضي الصفر.
-- الشرط `answer_time IS NOT NULL` يمنع كتابة صفرٍ كاذب في غير المُجابة،
-- و`>= start_time` يحمي من ساعة جهاز عُدِّلت بين الحقلين.
UPDATE dinstar_cdr
   SET ring_duration_seconds = EXTRACT(EPOCH FROM (answer_time - start_time))::int
 WHERE answer_time IS NOT NULL
   AND answer_time >= start_time
   AND COALESCE(ring_duration_seconds, 0) = 0;

-- ما لا يُحسَب يُعلَن مجهولًا صراحةً بدل صفرٍ موروث من الافتراضي المحذوف.
UPDATE dinstar_cdr
   SET ring_duration_seconds = NULL
 WHERE answer_time IS NULL
   AND ring_duration_seconds = 0;

-- ===== Snapshot of V42__Persistent_Gateway_Port_Reservations.sql (fresh install only) =====
-- V42 — حجز المنافذ الدائم: Postgres مصدر الحقيقة، Redis كاش سريع
-- المشكلة: portUsage كان ConcurrentHashMap في الذاكرة فقط — إعادة تشغيل واحدة
-- تُفقد كل الحجوزات فيُخصص منفذان لمكالمتين في آن واحد.
-- الحل: جدول دائم بفهرس فريد يمنع الحجز المزدوج على مستوى قاعدة البيانات
-- حتى مع تعدد نسخ الباكند، و TTL تلقائي يحرر المنفذ دون تدخل.

CREATE EXTENSION IF NOT EXISTS "pgcrypto";

CREATE TABLE IF NOT EXISTS gateway_port_reservations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    gateway_id UUID REFERENCES telecom_gateways(id) ON DELETE CASCADE,
    port_index INT NOT NULL CHECK (port_index BETWEEN 0 AND 31),
    reserved_by_user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    call_id VARCHAR(64) NOT NULL,
    target_number VARCHAR(32),
    reserved_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    expires_at TIMESTAMPTZ NOT NULL,
    -- يمنع حجز منفذ واحد مرتين في نفس اللحظة حتى مع تزامن كامل بين نسختين
    CONSTRAINT chk_reservation_ttl CHECK (expires_at > reserved_at)
);

-- فهرس فريد على (gateway_id, port_index, call_id): كل مكالمة لها حجز واحد.
-- الانتهاء يُدار في طبقة التطبيق: قبل إدراج حجز جديد، تُحذف المنتهية لنفس المنفذ.
CREATE UNIQUE INDEX IF NOT EXISTS uq_gateway_port_reservation_call
    ON gateway_port_reservations (gateway_id, port_index, call_id);

-- فهرس للتنظيف الدوري و للاستعلام السريع عن الحجوزات النشطة لبوابة
CREATE INDEX IF NOT EXISTS idx_gateway_reservations_expires
    ON gateway_port_reservations (expires_at);
CREATE INDEX IF NOT EXISTS idx_gateway_reservations_gateway_active
    ON gateway_port_reservations (gateway_id, port_index, expires_at);

-- فهرس للمستخدم: هل لديه حجز نشط؟ (يُستخدم للتحقق من منع مكالمتين متزامنتين)
CREATE INDEX IF NOT EXISTS idx_gateway_reservations_user_active
    ON gateway_port_reservations (reserved_by_user_id, expires_at);

COMMENT ON TABLE gateway_port_reservations IS 'حجوزات المنافذ الدائمة — Postgres مصدر الحقيقة، Redis كاش للقراءة السريعة. TTL يحرر المنفذ تلقائياً';
COMMENT ON INDEX uq_gateway_port_reservation_call IS 'كل مكالمة = حجز واحد؛ تكرار call_id على نفس المنفذ ممنوع';

-- ===== Snapshot of V43__Persistent_Pstn_Active_Calls.sql (fresh install only) =====
-- V43 — المكالمات النشطة الدائمة: ربط callId ↔ منفذ ↔ مستخدم
-- المشكلة: PstnActiveCallKeys كان Redis فقط — إعادة تشغيل Redis أو الباكند
-- تُفقد الربط فيُصبح المنفذ محجوزًا في الذاكرة لكن لا أحد يعرف لمن، فلا يُحرر
-- عند Hangup ويبقى المنفذ ميتًا حتى انتهاء TTL (30 دقيقة) بلا مكالمة.
-- الحل: جدول دائم يحفظ الربط مع فهرس فريد على call_id و TTL، و Redis كاش.

CREATE TABLE IF NOT EXISTS pstn_active_calls (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    call_id VARCHAR(64) NOT NULL,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    gateway_id UUID REFERENCES telecom_gateways(id) ON DELETE SET NULL,
    port_index INT NOT NULL CHECK (port_index BETWEEN 0 AND 31),
    target_number VARCHAR(32),
    started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    expires_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT chk_active_call_ttl CHECK (expires_at > started_at)
);

-- كل مكالمة لها سجل واحد فقط — يمنع التكرار حتى مع إعادة محاولة Asterisk
CREATE UNIQUE INDEX IF NOT EXISTS uq_pstn_active_call_id
    ON pstn_active_calls (call_id);

-- فهرس للبحث العكسي: من callId إلى userId (يُستخدم عند Hangup من AMI)
CREATE INDEX IF NOT EXISTS idx_pstn_active_call_lookup
    ON pstn_active_calls (call_id, user_id);

-- فهرس للمستخدم: call_id للمكالمات النشطة (التطبيق يحذف المنتهية قبل إدراج جديد)
CREATE INDEX IF NOT EXISTS idx_pstn_active_user_calls
    ON pstn_active_calls (user_id, expires_at);

-- فهرس للبحث عن المنافذ المشغولة لبوابة
CREATE INDEX IF NOT EXISTS idx_pstn_active_gateway_port
    ON pstn_active_calls (gateway_id, port_index, expires_at);

CREATE INDEX IF NOT EXISTS idx_pstn_active_expires
    ON pstn_active_calls (expires_at);

COMMENT ON TABLE pstn_active_calls IS 'ربط المكالمات النشطة الدائم — يضمن تحرير المنفذ حتى بعد فقدان Redis';

-- ===== Snapshot of V44__Call_Timeline_And_Analytics.sql (fresh install only) =====
-- V44 — Call Timeline, Memory Management & Analytics
-- تتبع مراحل المكالمة + إحصائيات الأداء + فهارس محسّنة

-- ═══════════════════════════════════════════════════════════════
-- 1) جدول timeline المكالمات
-- ═══════════════════════════════════════════════════════════════
CREATE TABLE IF NOT EXISTS pstn_call_timeline (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    call_id VARCHAR(64) NOT NULL REFERENCES pstn_active_calls(call_id) ON DELETE CASCADE,
    stage VARCHAR(20) NOT NULL CHECK (stage IN ('DIALING', 'RINGING', 'BRIDGING', 'ACTIVE', 'ENDED')),
    stage_data JSONB,
    started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    ended_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- فهرس للبحث السريع عن timeline مكالمة
CREATE INDEX IF NOT EXISTS idx_call_timeline_call_id
    ON pstn_call_timeline (call_id, started_at DESC);

-- فهرس للبحث عن المراحل حسب الوقت
CREATE INDEX IF NOT EXISTS idx_call_timeline_started_at
    ON pstn_call_timeline (started_at DESC);

COMMENT ON TABLE pstn_call_timeline IS 'تتبع مراحل المكالمة (DIALING→RINGING→BRIDGING→ACTIVE→ENDED)';

-- ═══════════════════════════════════════════════════════════════
-- 2) تحسينات على جدول gateway_route_decisions
-- ═══════════════════════════════════════════════════════════════
CREATE INDEX IF NOT EXISTS idx_route_decisions_created_at
    ON gateway_route_decisions (created_at DESC);

CREATE INDEX IF NOT EXISTS idx_route_decisions_outcome
    ON gateway_route_decisions (outcome, created_at DESC);

-- ═══════════════════════════════════════════════════════════════
-- 3) تحسينات على جدول dinstar_cdr
-- ═══════════════════════════════════════════════════════════════
CREATE INDEX IF NOT EXISTS idx_cdr_start_time
    ON dinstar_cdr (start_time DESC);

CREATE INDEX IF NOT EXISTS idx_cdr_status
    ON dinstar_cdr (status, start_time DESC);

CREATE INDEX IF NOT EXISTS idx_cdr_direction
    ON dinstar_cdr (direction, start_time DESC);

-- ═══════════════════════════════════════════════════════════════
-- 4) View لإحصائيات الأداء اليومية
-- ═══════════════════════════════════════════════════════════════
CREATE OR REPLACE VIEW v_pstn_daily_stats AS
SELECT
    DATE(start_time)::date as stat_date,
    COUNT(*) as total_calls,
    COUNT(*) FILTER (WHERE status = 'answered') as answered_calls,
    COUNT(*) FILTER (WHERE status = 'no_answer') as no_answer_calls,
    COUNT(*) FILTER (WHERE status = 'busy') as busy_calls,
    COUNT(*) FILTER (WHERE status = 'failed') as failed_calls,
    AVG(duration_seconds) as avg_duration,
    AVG(ring_duration_seconds) as avg_ring_duration,
    COUNT(DISTINCT gateway_id) as gateways_used,
    COUNT(DISTINCT caller_number) as unique_callers
FROM dinstar_cdr
GROUP BY DATE(start_time)::date
ORDER BY stat_date DESC;

COMMENT ON VIEW v_pstn_daily_stats IS 'إحصائيات يومية مجمعة للمكالمات';

-- ═══════════════════════════════════════════════════════════════
-- 5) دالة لحساب إحصائيات الوقت الحقيقي
-- ═══════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION get_pstn_realtime_stats(hours_back INTEGER DEFAULT 1)
RETURNS TABLE (
    total_calls BIGINT,
    active_calls BIGINT,
    avg_duration DOUBLE PRECISION,
    success_rate DOUBLE PRECISION
) AS $$
BEGIN
    RETURN QUERY
    SELECT
        COUNT(*)::BIGINT,
        (SELECT COUNT(*) FROM pstn_active_calls WHERE expires_at > NOW())::BIGINT,
        AVG(duration_seconds),
        CASE WHEN COUNT(*) = 0 THEN 0.0
             ELSE COUNT(*) FILTER (WHERE status = 'answered')::DOUBLE PRECISION / COUNT(*)
        END
    FROM dinstar_cdr
    WHERE start_time >= NOW() - (hours_back || ' hours')::INTERVAL;
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION get_pstn_realtime_stats(INTEGER) IS 'حساب إحصائيات PSTN اللحظية لـ N ساعة الماضية';

-- ===== Snapshot of V45__Cdr_Semantics_Reason_And_End_Time.sql (fresh install only) =====
-- V45__Cdr_Semantics_Reason_And_End_Time.sql
-- ═══════════════════════════════════════════════════════════════════════
-- تصحيح دلالة عمودَين في `dinstar_cdr`:
--   1. `hangup_cause` ← حقل `reason` (السبب) لا `hangup` (الطرف المنهي)
--   2. `end_time` يُحسَب بدل أن يبقى فارغًا في كل صفّ
-- ═══════════════════════════════════════════════════════════════════════
--
-- ## العطل الأول: `hangup_cause` كان يحمل الطرف لا السبب
--
-- ردّ `get_cdr` من UC2000-VE يحمل حقلَين متمايزَين:
--
--   "hangup": "calling"          ← **مَن** أنهى المكالمة (calling/called)
--   "reason": "NORMAL HANG UP"   ← **لماذا** انتهت
--
-- وكان المُدرِجان يكتبان `hangup` في عمود اسمه `hangup_cause`. النتيجة: 110
-- صفًّا من 110 تحمل القيمة `calling` — أي «المتصل أنهى» — وهي جملة صحيحة عن
-- الطرف لكنها لا تقول شيئًا عن السبب. فتحليل أسباب الإخفاق (لا رد؟ مشغول؟
-- شبكة؟) كان مستحيلًا: العمود المخصَّص للسبب لا يحمل سببًا قطّ، ويُظهر توزيعًا
-- من قيمة واحدة يتيمة تُقرأ كأن كل المكالمات انتهت بالطريقة نفسها.
--
-- لاحظ أن `callOutcome` لم يتأثّر: هو يقرأ `hangup` أيضًا لكن لتصنيف الحالة
-- (`answered|no_answer|busy|failed|cancelled`)، وذاك استخدام مقصود ودقيق.
-- الخطأ كان في **تخزين** `hangup` تحت اسم `hangup_cause`.
--
-- ## العطل الثاني: `end_time` فارغ في كل صفّ
--
-- العمود موجود في V15 ولم يكتبه أيّ مُدرِج (0/110). وهو مشتقّ بالكامل من
-- حقول موجودة:
--
--   * مُجابة:      `answer_time + duration_seconds`
--     (`duration` في ردّ الجهاز هو زمن التحدُّث بعد الإجابة — تؤكّده العيّنة:
--      `start=17:55:08`, `answer=17:55:11`, `duration=2` ⇒ رنين 3ث ثم تحدُّث 2ث)
--   * غير مُجابة:  `start_time + ring_duration_seconds + duration_seconds`
--     (لا زمن إجابة، فالنهاية بعد الرنين مباشرةً)
--
-- بلا هذا العمود كان كل استعلام «كم استغرقت المكالمة من البداية إلى النهاية»
-- أو «ما التراكب الزمني بين مكالمتين على منفذَين» يتطلّب إعادة الحساب في كل
-- استدعاء، ولا فهرس يخدمه.
--
-- ## الاتّساق مع الكود
--
-- [DinstarApiContract.Cdr.INSERT_SQL] صار يُدرج `end_time` ويكتب `reason` في
-- `hangup_cause`، و[DinstarApiContract.Cdr.endTime] يُشتقّ القيمة بالمنطق
-- نفسه المكتوب أدناه. هذه الهجرة تُصلح الصفوف **القائمة**؛ والصفوف الجديدة
-- تُدرَج صحيحةً من المصدر.
--
-- ## لماذا `raw_data` هو المصدر
--
-- كل صفّ يحفظ ردّ الجهاز الخام في `raw_data` (V40)، فالتصحيح لا يحتاج
-- استدعاء الجهاز مجدَّدًا ولا يفقد شيئًا: `reason` محفوظ هناك حرفيًّا.

-- ── 1. hangup_cause ← reason ────────────────────────────────────────────
-- الشرط `raw_data ? 'reason'` يحمي الصفوف التي لا تحمل الحقل (إصدار أقدم من
-- البرنامج الثابت): تُترك كما هي بدل أن تُفرَّغ.
UPDATE dinstar_cdr
   SET hangup_cause = raw_data->>'reason'
 WHERE raw_data ? 'reason'
   AND (raw_data->>'reason') <> ''
   AND (hangup_cause IS DISTINCT FROM raw_data->>'reason');

-- ── 2. end_time محسوب ───────────────────────────────────────────────────
-- `make_interval` لا سَلسَلة نصّية: بناء `(x || ' seconds')::interval` يعتمد
-- على `lc_numeric` ويكسر مع أعداد كبيرة، و`make_interval` يأخذ عددًا صحيحًا.
UPDATE dinstar_cdr
   SET end_time = CASE
           WHEN answer_time IS NOT NULL
               THEN answer_time + make_interval(secs => duration_seconds)
           ELSE start_time + make_interval(
                    secs => COALESCE(ring_duration_seconds, 0) + duration_seconds
                )
       END
 WHERE end_time IS NULL
   AND start_time IS NOT NULL;

-- ── 3. توثيق الدلالة في المخطَّط نفسه ──────────────────────────────────
-- التعليق يمنع تكرار الالتباس: القارئ التالي يرى الفرق بين reason وhangup
-- في القاعدة لا في تاريخ Git.
COMMENT ON COLUMN dinstar_cdr.hangup_cause IS
    'سبب الإنهاء من الجهاز — حقل reason (NORMAL HANG UP / NO ANSWER / USER BUSY...). '
    'حقل hangup الخام (calling/called) يدلّ على الطرف المنهي لا السبب، ويُستخدم '
    'لتصنيف status عبر callOutcome فقط.';

COMMENT ON COLUMN dinstar_cdr.end_time IS
    'زمن نهاية المكالمة، مشتقّ لا مُصدَر من الجهاز: '
    'مُجابة = answer_time + duration_seconds؛ '
    'غير مُجابة = start_time + ring_duration_seconds + duration_seconds.';

-- ── 4. فهرس للاستعلامات الزمنية على النهاية ────────────────────────────
-- تقارير التراكب والإشغال ترتّب بـ end_time؛ بلا فهرس تُمسح الجدول كاملًا.
CREATE INDEX IF NOT EXISTS idx_dinstar_cdr_end_time
    ON dinstar_cdr (end_time DESC)
    WHERE end_time IS NOT NULL;

-- ===== Snapshot of V46__Yemen_Mobile_Cellular_Multi_Operator.sql (fresh install only) =====
-- V46 fresh baseline: skip tariff writes (table was never created).
-- ── 2. radio_type أوسع: LTE-FDD/... يتجاوز VARCHAR(20) ──────────────────
-- 'LTE-FDD B3/VoLTE' و'CDMA2000 1xEV-DO' تُقصّ إلى 20 حرفاً فتضيع.
-- v_pstn_reconcile يعتمد على العمود فيجب إسقاطه أولاً ثم إعادة بنائه (V38).
DROP VIEW IF EXISTS v_pstn_reconcile;
ALTER TABLE gateway_port_snapshots ALTER COLUMN radio_type TYPE VARCHAR(60);
CREATE OR REPLACE VIEW v_pstn_reconcile AS
SELECT
    g.id                          AS gateway_id,
    g.host                        AS gateway_host,
    g.model                       AS gateway_model,
    g.enabled                     AS gateway_enabled,
    ps.port_index                 AS port_index,
    ps.radio_type                 AS radio_type,
    ps.registration_state         AS registration_state,
    ps.call_state                 AS call_state,
    ps.signal_raw                 AS signal_raw,
    ps.signal_dbm                 AS signal_dbm,
    ps.signal_percent             AS signal_percent,
    ps.signal_usable              AS signal_usable,
    ps.operator_name              AS operator_name,
    ps.gprs_state                 AS gprs_state,
    ps.sim_number_masked          AS live_number_masked,
    ps.imsi_masked                AS imsi_masked,
    ps.iccid_masked               AS iccid_masked,
    ps.observed_at                AS observed_at,
    u.id                          AS bound_user_id,
    u.red_id                      AS bound_red_id,
    u.username                    AS bound_username,
    u.pstn_number                 AS bound_number,
    CASE
        WHEN u.id IS NULL AND ps.signal_usable THEN 'UNBOUND_HAS_SIM'
        WHEN u.id IS NOT NULL AND ps.sim_number_masked IS NULL AND ps.signal_usable THEN 'NEEDS_NUMBER_LEARNING'
        WHEN u.id IS NOT NULL AND ps.signal_usable = false AND ps.sim_number_masked IS NULL THEN 'ORPHAN_BINDING_NEEDS_CLEAR'
        WHEN u.id IS NULL THEN 'EMPTY'
        ELSE 'BOUND'
    END AS reconcile_status
FROM telecom_gateways g
LEFT JOIN gateway_port_snapshots ps ON ps.gateway_id = g.id
LEFT JOIN users u ON u.pstn_gateway_id = g.id AND u.pstn_port_index = ps.port_index
WHERE g.vendor = 'DINSTAR';

-- ── 3. gsm_code هو release cause لكل RAT لا GSM فقط — وثّق لا تُعد تسمية ──
-- إعادة التسمية تكسر API؛ التعليق يمنع سوء القراءة ليمن موبايل LTE (380/486).
COMMENT ON COLUMN dinstar_cdr.gsm_code IS
    'رمز الإطلاق من الشبكة (حقل gsm_code/hangup الخام) — لكل تقنيات الراديو '
    '(GSM/CDMA2000/LTE)، ليس GSM فقط. يمن موبايل LTE تُرجع نفس الحقل عبر IMS.';

-- ── 4. بوابة البذرة: عطّل الأشباح .2/.3، وحّد على .1 الحي ───────────────
-- بعد تغيير .env إلى DINSTAR_IPS=192.168.11.1 تبقى صفوف .2/.3 مفعّلة
-- في telecom_gateways فيستمر heartbeat في Connect timed out ويختارها
-- LoadBalancer. هذا يطابق سلوك ensureSeedGateway دون حذف التاريخ.
UPDATE telecom_gateways SET enabled = false, updated_at = CURRENT_TIMESTAMP
 WHERE host IN ('192.168.11.2', '192.168.11.3') AND enabled = true;

-- ── 5. فهرس مطابقة داخل-الشبكة بعد تصحيح البادئات ──────────────────────
CREATE INDEX IF NOT EXISTS idx_dinstar_cdr_prefix_time
    ON dinstar_cdr (start_time DESC)
    WHERE start_time IS NOT NULL;

-- ===== Snapshot of V47__Atomic_Gateway_Port_Reservation.sql (fresh install only) =====
-- ═══════════════════════════════════════════════════════════════════════════
-- V47 — حجز المنفذ يصبح ذريًّا فعلًا + تحرير دقيق بالمكالمة
-- ═══════════════════════════════════════════════════════════════════════════
-- المشكلة التي يعالجها هذا الترحيل:
--
-- `PersistentReservationService.tryReservePort` كُتب على أساس فهرس اسمه
-- `uq_gateway_port_active_reservation` يمنع حجزين حيَّين لنفس (بوابة، منفذ).
-- ذلك الفهرس **غير موجود في أي ترحيل**. الموجود فعلًا هو
-- `uq_gateway_port_reservation_call` على (gateway_id, port_index, call_id)،
-- و`call_id` فريد لكل مكالمة ⇒ الـINSERT لا يتعارض أبدًا ⇒ الدالة لا تُرجع
-- `false` من قاعدة البيانات قطّ، فالحجز «الذرّي» لم يكن يمنع شيئًا:
-- مكالمتان متزامنتان تحصلان على المنفذ نفسه.
--
-- لماذا لم يُكتب الفهرس الصحيح؟ لأن `WHERE expires_at > NOW()` مستحيل في
-- فهرس PostgreSQL: predicate الفهرس يجب أن يكون IMMUTABLE و`NOW()` ليست
-- كذلك. الحل الصحيح ليس فهرسًا شرطيًا بل فهرس فريد بسيط على
-- (gateway_id, port_index) مع كتابة «استيلاء» ذرّية تستبدل الصف المنتهي:
--   INSERT … ON CONFLICT (gateway_id, port_index)
--   DO UPDATE … WHERE gateway_port_reservations.expires_at <= NOW()
-- فإن كان الحجز حيًّا لا يتغيّر شيء ويعود عدد الصفوف صفرًا = مرفوض،
-- وإن كان منتهيًا يُستولى عليه في نفس العبارة بلا نافذة سباق.
--
-- NULLS NOT DISTINCT: `gateway_id` قد يكون NULL (نشر ببوابة واحدة). بلا
-- هذه الصيغة تسمح PostgreSQL بعدد لا نهائي من صفوف NULL على المنفذ نفسه
-- فيسقط الضمان في أكثر الحالات شيوعًا. الصيغة مدعومة من PostgreSQL 15+،
-- والنشر هنا على 16.9.

-- 1) إزالة التعارضات القائمة قبل فرض القيد: نُبقي الأحدث انتهاءً لكل
--    (بوابة، منفذ) ونحذف الباقي. هذا آمن لأن الصفوف حجوزات مؤقتة.
DELETE FROM gateway_port_reservations r
WHERE EXISTS (
    SELECT 1 FROM gateway_port_reservations k
    WHERE k.gateway_id IS NOT DISTINCT FROM r.gateway_id
      AND k.port_index = r.port_index
      AND (k.expires_at, k.id) > (r.expires_at, r.id)
);

-- 2) الفهرس الفريد الحقيقي — حجز حيّ واحد لكل منفذ.
CREATE UNIQUE INDEX IF NOT EXISTS uq_gateway_port_active_reservation
    ON gateway_port_reservations (gateway_id, port_index) NULLS NOT DISTINCT;

-- 3) الفهرس القديم صار زائدًا (أوسع من الجديد) وضارًّا: تعارض عليه يرفع
--    استثناءً بدل أن يسلك مسار ON CONFLICT المُستنتَج، فيفشل الاستيلاء
--    المشروع على حجز منتهٍ.
DROP INDEX IF EXISTS uq_gateway_port_reservation_call;

COMMENT ON INDEX uq_gateway_port_active_reservation IS
    'حجز واحد لكل (بوابة، منفذ). الانتهاء يُدار بالاستيلاء الذرّي في tryReservePort لا بشرط فهرس (NOW() ليست IMMUTABLE).';

-- ===== Snapshot of V48__Gateway_Config_Backup_History.sql (fresh install only) =====
-- ═══════════════════════════════════════════════════════════════════════════
-- V48 — إضافة جداول النسخ الاحتياطي والسجل الصحي للبوابات
-- ═══════════════════════════════════════════════════════════════════════════
-- المشكلة التي يعالجها هذا الترحيل:
--
-- DinstarHardwareService يحتاج الآن إلى تخزين نسخ احتياطية
-- من تكوينات البوابات وسجلات صحية، لكن لا توجد جداول مخصصة
-- لذلك. أضفنا الجداول التالية لدعم:
--   • backupConfig / restoreConfig / listBackups
--   • healthCheck / fleetHealthSummary
--
-- هذه الجداول تُضاف للبيئة الإنتاجية فقط ولا تؤثر
-- على النشرات ذات الجهاز الواحد.

-- 1) جدول النسخ الاحتياطي لتكوينات البوابات
CREATE TABLE IF NOT EXISTS gateway_config_backups (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    gateway_id      UUID NOT NULL REFERENCES telecom_gateways(id) ON DELETE CASCADE,
    config_json     JSONB NOT NULL,
    actor_id        UUID,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_gw_config_backup_gateway
    ON gateway_config_backups (gateway_id, created_at DESC);

COMMENT ON TABLE gateway_config_backups IS
    'نسخ احتياطية لتكوينات البوابات. يُستخدم لـ backupConfig/restoreConfig.';

-- 2) جدول السجل الصحي للبوابات (health check history)
CREATE TABLE IF NOT EXISTS gateway_health_history (
    id              BIGSERIAL PRIMARY KEY,
    gateway_id      UUID NOT NULL REFERENCES telecom_gateways(id) ON DELETE CASCADE,
    reachable       BOOLEAN NOT NULL,
    model           VARCHAR(64),
    port_total      INT DEFAULT 0,
    port_registered INT DEFAULT 0,
    port_healthy    INT DEFAULT 0,
    error_message   TEXT,
    checked_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_gw_health_gateway_time
    ON gateway_health_history (gateway_id, checked_at DESC);

ALTER TABLE gateway_health_history
    ADD CONSTRAINT chk_gw_health_ports CHECK (
        port_total >= port_registered AND port_registered >= port_healthy
    );

COMMENT ON TABLE gateway_health_history IS
    'سجل الفحوصات الصحية للبوابات. يُستخدم لـ healthCheck/fleetHealthSummary.';

-- 3) جدول عمليات البوابات (للتسجيل التدقيقي)
--    يتم إنشاؤه بالفعل عبر V12 لكن نُضيف الأعمدة المفقودة
ALTER TABLE gateway_operations
    ADD COLUMN IF NOT EXISTS duration_ms INT;

ALTER TABLE gateway_operations
    ADD COLUMN IF NOT EXISTS call_id UUID REFERENCES pstn_active_calls(id);

CREATE INDEX IF NOT EXISTS idx_gw_ops_gateway_time
    ON gateway_operations (gateway_id, completed_at DESC);

COMMENT ON TABLE gateway_operations IS
    'سجل عمليات البوابات مع مدة التنفيذ ومعرّف المكالمة المرتبطة.';

-- 4) تأكيد جدول telecom_gateways يحتوي على الأعمدة المطلوبة
DO $$ BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_name = 'telecom_gateways' AND column_name = 'model'
    ) THEN
        ALTER TABLE telecom_gateways ADD COLUMN model VARCHAR(64) DEFAULT 'UNKNOWN';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_name = 'telecom_gateways' AND column_name = 'vendor'
    ) THEN
        ALTER TABLE telecom_gateways ADD COLUMN vendor VARCHAR(64) DEFAULT 'DINSTAR';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_name = 'telecom_gateways' AND column_name = 'api_port'
    ) THEN
        ALTER TABLE telecom_gateways ADD COLUMN api_port INT DEFAULT 443;
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_name = 'telecom_gateways' AND column_name = 'scheme'
    ) THEN
        ALTER TABLE telecom_gateways ADD COLUMN scheme VARCHAR(10) DEFAULT 'https';
    END IF;
END $$;

-- ===== Snapshot of V49__Sms_Result_Delivery_Incoming_Tables.sql (fresh install only) =====
-- V49: جداول سجلات SMS التي يكتبها DinstarApiService (saveSmsResult/saveSmsDeliveryStatus/saveIncomingSms)
-- هذه الجداول لم تُعرّف في أي هجرة سابقة؛ الإدخالات كانت تفشل بصمت داخل try/catch.
-- آمنة تماماً: إنشاء فقط مع IF NOT EXISTS، بلا تعديل لأي جدول قائم.

CREATE TABLE IF NOT EXISTS dinstar_sms_result (
    id SERIAL PRIMARY KEY,
    gateway_id UUID REFERENCES telecom_gateways(id) ON DELETE CASCADE,
    user_id TEXT,
    message_id VARCHAR(100),
    status VARCHAR(30),
    status_code VARCHAR(30),
    completed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_sms_result_gateway ON dinstar_sms_result(gateway_id);
CREATE INDEX IF NOT EXISTS idx_sms_result_user ON dinstar_sms_result(user_id);

CREATE TABLE IF NOT EXISTS dinstar_sms_delivery_status (
    id SERIAL PRIMARY KEY,
    gateway_id UUID REFERENCES telecom_gateways(id) ON DELETE CASCADE,
    phone_number VARCHAR(50),
    status VARCHAR(30),
    status_code VARCHAR(30),
    completed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_sms_delivery_gateway ON dinstar_sms_delivery_status(gateway_id);
CREATE INDEX IF NOT EXISTS idx_sms_delivery_phone ON dinstar_sms_delivery_status(phone_number);

CREATE TABLE IF NOT EXISTS dinstar_incoming_sms (
    id SERIAL PRIMARY KEY,
    gateway_id UUID REFERENCES telecom_gateways(id) ON DELETE CASCADE,
    phone_number VARCHAR(50),
    text TEXT,
    received_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_incoming_sms_gateway ON dinstar_incoming_sms(gateway_id);
CREATE INDEX IF NOT EXISTS idx_incoming_sms_phone ON dinstar_incoming_sms(phone_number);

-- ===== Snapshot of V50__chat_completeness.sql (fresh install only) =====
-- ══════════════════════════════════════════════════════════════════
-- V50: اكتمال المحادثات — قوائم البث، مرآة التفاعلات، دليل المتصلين
-- Chat completeness — broadcast lists, reaction mirror, caller directory
-- ══════════════════════════════════════════════════════════════════
-- آمنة تمامًا: إنشاء فقط مع IF NOT EXISTS، بلا تعديل لأي جدول قائم.
-- 1. broadcast_lists + broadcast_members — قوائم بث (توزيع E2EE من العميل)
-- 2. message_reactions — مرآة Postgres للتفاعلات المخزنة في Mongo
-- 3. caller_directory + phone_spam_reports — بحث عكسي عن الأرقام + بلاغات إزعاج
-- ══════════════════════════════════════════════════════════════════

-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
-- 1. قوائم البث — Broadcast Lists (مثل واتساب)
-- المالك يوزع من جهازه (E2EE fan-out)؛ الخادم يحفظ العضوية فقط.
-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
CREATE TABLE IF NOT EXISTS broadcast_lists (
    id UUID PRIMARY KEY,
    owner_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT broadcast_lists_name_check CHECK (char_length(name) BETWEEN 1 AND 100)
);
CREATE INDEX IF NOT EXISTS idx_broadcast_lists_owner ON broadcast_lists(owner_id, created_at DESC);

CREATE TABLE IF NOT EXISTS broadcast_members (
    list_id UUID NOT NULL REFERENCES broadcast_lists(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    added_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (list_id, user_id)
);
CREATE INDEX IF NOT EXISTS idx_broadcast_members_user ON broadcast_members(user_id);

COMMENT ON TABLE broadcast_lists IS 'V50: قوائم البث — العضوية فقط، التوزيع E2EE من جهاز المالك';
COMMENT ON TABLE broadcast_members IS 'V50: أعضاء قوائم البث';

-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
-- 2. مرآة التفاعلات — Message Reactions (المصدر: Mongo reactions[])
-- تفاعل واحد لكل مستخدم على كل رسالة (PRIMARY KEY(message_uuid, user_id)).
-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
CREATE TABLE IF NOT EXISTS message_reactions (
    message_uuid TEXT NOT NULL,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    emoji TEXT NOT NULL,
    reacted_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (message_uuid, user_id),
    CONSTRAINT message_reactions_emoji_check CHECK (char_length(emoji) BETWEEN 1 AND 16)
);
CREATE INDEX IF NOT EXISTS idx_message_reactions_message ON message_reactions(message_uuid);

COMMENT ON TABLE message_reactions IS 'V50: مرآة Postgres لتفاعلات الرسائل (المصدر MongoDB)';

-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
-- 3. دليل المتصلين — Caller Directory + بلاغات الإزعاج
-- بحث عكسي عن أرقام GSM (يكمل passthrough الخام في DinstarEventListener).
-- phone بلا FK في البلاغات عمدًا: الإبلاغ عن رقم مجهول يجب أن ينجح
-- بلا قيود ترتيب (السطر يُنشأ في caller_directory أولًا من المتحكم).
-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
CREATE TABLE IF NOT EXISTS caller_directory (
    phone TEXT PRIMARY KEY,
    display_name TEXT NOT NULL,
    spam_score INT NOT NULL DEFAULT 0,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT caller_directory_spam_check CHECK (spam_score >= 0),
    CONSTRAINT caller_directory_name_check CHECK (char_length(display_name) BETWEEN 1 AND 100)
);

CREATE TABLE IF NOT EXISTS phone_spam_reports (
    id SERIAL PRIMARY KEY,
    phone TEXT NOT NULL,
    reporter UUID REFERENCES users(id) ON DELETE SET NULL,
    reason TEXT,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT phone_spam_reason_check CHECK (reason IS NULL OR char_length(reason) <= 500)
);
CREATE INDEX IF NOT EXISTS idx_spam_reports_phone ON phone_spam_reports(phone);
CREATE INDEX IF NOT EXISTS idx_spam_reports_reporter ON phone_spam_reports(reporter) WHERE reporter IS NOT NULL;

COMMENT ON TABLE caller_directory IS 'V50: دليل المتصلين — بحث عكسي عن أرقام GSM مع درجة إزعاج مجتمعية';
COMMENT ON TABLE phone_spam_reports IS 'V50: بلاغات الإزعاج عن أرقام الهاتف';

-- ===== Snapshot of V51__Typing_Privacy.sql (fresh install only) =====
-- ══════════════════════════════════════════════════════════════════
-- V51: خصوصية مؤشر الكتابة — typing_indicators في user_privacy_settings
-- Typing privacy — sender controls who sees their typing indicator
-- ══════════════════════════════════════════════════════════════════
-- آمنة: عمود جديد بقيمة افتراضية EVERYONE (لا يكسر الصفوف القائمة)،
-- مع قيد تحقق مستقل حتى لا نمس القيد الأصلي privacy_level_check.
-- ══════════════════════════════════════════════════════════════════

ALTER TABLE user_privacy_settings
    ADD COLUMN IF NOT EXISTS typing_indicators VARCHAR(20) NOT NULL DEFAULT 'EVERYONE';

ALTER TABLE user_privacy_settings DROP CONSTRAINT IF EXISTS privacy_typing_check;
ALTER TABLE user_privacy_settings ADD CONSTRAINT privacy_typing_check CHECK (
    typing_indicators IN ('EVERYONE','CONTACTS','CONTACTS_EXCEPT','ONLY_SHARE_WITH','NOBODY')
);

COMMENT ON COLUMN user_privacy_settings.typing_indicators IS 'V51: من يرى مؤشر الكتابة — يفرضه RedMasterHandler قبل بث TYPING';

-- ===== Snapshot of V52__Drop_Cancelled_Pstn_Dinstar_Scope.sql (fresh install only) =====
-- V52__Drop_Cancelled_Pstn_Dinstar_Scope.sql
-- ═══════════════════════════════════════════════════════════════════════
-- القبول النهائي (DoD): إسقاط كل ما تبقى من نطاق PSTN/Dinstar/الهاتف اليمني
-- الملغي (المرحلة 8). الهجرات القديمة (V2..V49) تُترك كما هي عمدًا — حذف هجرة
-- مطبَّقة يكسر سلسلة Flyway — وهذه الهجرة هي الإغلاق الرسمي للنطاق.
--
-- تحقق قبل الكتابة (2026-09-15):
--  - صفر مرجع Kotlin (main+test) لأي جدول/عمود/عرض هنا.
--  - كيان UserAccount لا يملك حقول PSTN — JPA لن يلمس الأعمدة المسقطة.
--  - كل المفاتيح الأجنبية الداخلية (الأبناء ← telecom_gateways/sms_templates/
--    pstn_active_calls/dinstar_sms_templates) تنشأ من هجرات ميتة أيضًا —
--    لا جدول حي يشير لجدول ميت، فـ CASCADE آمن ولا يطال إلا الميت.
--  - العروض الحية (v_user_stats/v_message_stats/v_call_stats/v_trending_hashtags)
--    لا تقرأ أي جدول هنا — تقرأ users/call_history فقط.
--  - جداول V15 (rate_limit/encryption/prekeys/receipts) غير مشار إليها كوديًا
--    لكنها خارج النطاق الملغي — تُركت عمدًا لفرز المالك، لا تُسقط هنا.
-- ═══════════════════════════════════════════════════════════════════════

-- 1) العروض الميتة أولًا (تعتمد على الجداول الميتة).
DROP VIEW IF EXISTS v_pstn_reconcile;
DROP VIEW IF EXISTS v_pstn_daily_stats;
DROP VIEW IF EXISTS v_dinstar_recent_calls;
DROP VIEW IF EXISTS v_dinstar_gateway_stats;
DROP VIEW IF EXISTS v_dinstar_active_alerts;

-- 2) فهارس users على الأعمدة الملغاة (تموت مع الأعمدة، لكن صريح أفضل).
DROP INDEX IF EXISTS ux_users_pstn_number;
DROP INDEX IF EXISTS idx_users_pstn_number;
DROP INDEX IF EXISTS idx_users_pstn_gateway_port;

-- 3) قيود users الملغاة (V5/V34/V38).
ALTER TABLE users DROP CONSTRAINT IF EXISTS users_pstn_daily_limit_check;
ALTER TABLE users DROP CONSTRAINT IF EXISTS chk_users_pstn_port_range;
ALTER TABLE users DROP CONSTRAINT IF EXISTS chk_users_pstn_binding_consistency;
ALTER TABLE users DROP CONSTRAINT IF EXISTS uq_users_pstn_port;

-- 4) أعمدة users الملغاة (V5/V34).
ALTER TABLE users DROP COLUMN IF EXISTS pstn_enabled;
ALTER TABLE users DROP COLUMN IF EXISTS pstn_daily_limit;
ALTER TABLE users DROP COLUMN IF EXISTS pstn_gateway_id;
ALTER TABLE users DROP COLUMN IF EXISTS pstn_port_index;
ALTER TABLE users DROP COLUMN IF EXISTS pstn_number;

-- 5) الجداول الميتة (35) — V2/V12/V18/V23/V25/V26_1/V33/V36/V39/V42/V43/V44/V48/V49.
-- CASCADE للفهارس/المفاتيح الداخلية فقط — لا تابع حي لأيٍّ منها (موثّق أعلاه).
DROP TABLE IF EXISTS
    dinstar_config,
    dinstar_ports,
    dinstar_logs,
    dinstar_device_status,
    dinstar_cdr,
    dinstar_sms_log,
    dinstar_ussd_log,
    dinstar_sms_templates,
    dinstar_sms_scheduled,
    dinstar_sms_result,
    dinstar_sms_delivery_status,
    dinstar_incoming_sms,
    dinstar_sms_cursor,
    dinstar_port_control,
    dinstar_daily_stats,
    dinstar_alerts,
    dinstar_config_changes,
    telecom_gateways,
    gateway_port_snapshots,
    gateway_operations,
    gateway_sim_inventory,
    gateway_route_decisions,
    gateway_port_reservations,
    gateway_config_backups,
    gateway_health_history,
    pstn_active_calls,
    pstn_call_timeline,
    sms_templates,
    scheduled_sms,
    sms_messages,
    sms_conversation_read,
    port_control_state,
    number_learning_config,
    number_learning_pool,
    number_learning_calls
CASCADE;

-- ===== Snapshot of V53__Drop_Unreferenced_V15_Tables.sql (fresh install only) =====
-- V53__Drop_Unreferenced_V15_Tables.sql
-- ═══════════════════════════════════════════════════════════════════════
-- إكمال أسطوري 2026-09-15: إسقاط جداول V15 الأربعة غير المشار إليها إطلاقًا.
--
-- تحقق قبل الكتابة:
--  - صفر مرجع في كل الشجرة المشحونة (Kotlin بما فيه الاختبارات، ts/tsx/cjs/mjs،
--    js، proto، sh، ps1، nginx) — المراجع الوحيدة 3 هجرات: الإنشاء (V15) +
--    فهرس واحد (V26) + تعليقان (V32).
--  - ليست هدفًا لأي مفتاح أجنبي (فُحص كل REFERENCES في الهجرات).
--  - الفهرس الوحيد عليها (idx_messages_delivery_receipts_message) يموت مع الجدول.
-- هذه الجداول خارج النطاق الملغي (V52) — لكنها بنية ميتة بلا قارئ ولا كاتب،
-- وإبقاؤها يُبقي سطحًا مضللًا ("فوترة/تشفير" بلا كود). تُسقط هنا بلا CASCADE
-- (لا توابع عليها أصلًا — وإن وُجدت في بيئة شاذة فالفشل الصريح أفضل من الحذف الصامت).
--
-- ملاحظة انحراف سابق (ليس من هذه الهجرة): جدول `pstn_tariffs` يُحدِثه V46
-- (UPDATE/INSERT) دون أن ينشئه أي ملف هجرة في الشجرة — أي قاعدة جديدة تفشل
-- عند V46. لا يمكن إصلاح ذلك بهجرة لاحقة (ترتيب Flyway) ولا بتعديل V46
-- (هجرة مطبَّقة: التعديل يكسر checksums). الإصلاح الصحيح من جهة المالك عبر
-- Flyway repair/baseline عند الحاجة لتثبيت جديد. موثّق هنا لمنع المفاجآت.
-- ═══════════════════════════════════════════════════════════════════════

DROP TABLE IF EXISTS rate_limit_rules;
DROP TABLE IF EXISTS encryption_sessions;
DROP TABLE IF EXISTS sent_prekey_records;
DROP TABLE IF EXISTS message_delivery_receipts;

